'BarcodeSymbologyTooltip' => 'உங்கள் பொருள் லேபிளுடன் பொருந்தும் பார்கோடு வடிவம். பெரும்பாலான பொருட்களுக்கு CODE128 பாதுகாப்பான இயல்புத் தேர்வு.',
'ProductCodeTooltip' => 'இந்தப் பொருளுக்கான தனித்துவமான அடையாளம். ஏற்கனவே உள்ள பார்கோடை ஸ்கேன் செய்யவும் அல்லது ஒன்றை உருவாக்க பார்கோடு பொத்தானைக் கிளிக் செய்யவும். மேலே உள்ள சிம்பாலஜி குறியீட்டுடன் பொருந்துவதை உறுதிசெய்யவும்.',
