'Barcode_GTIN_Placeholder' => 'எ.கா. 0123456789012',
'SubcategoriesMultiTooltip' => 'விருப்பத்தேர்வு. தேர்வுசெய்த வகைகளுக்குச் சொந்தமான ஒன்று அல்லது அதற்கு மேற்பட்ட துணை வகைகளைத் தேர்வுசெய்யவும். பழைய API-கள் மற்றும் வடிகட்டிகளுக்காக முதலாவது முதன்மைத் துணை வகையாகச் சேமிக்கப்படும்.',
