'Online_Store_Accounts' => 'ஆன்லைன் கடைக் கணக்குகள்',
'Customers_without_login_alert' => 'இவர்கள் இன்னும் ஆன்லைன் கடைக் கணக்கு இல்லாத உங்கள் POS / நேரடி வாடிக்கையாளர்கள். வாடிக்கையாளர் உள்நுழைந்து உங்கள் ஆன்லைன் கடையில் வாங்க, கடை உள்நுழைவை (மின்னஞ்சல் + கடவுச்சொல்) உருவாக்க "கணக்கைப் பதிவுசெய்" என்பதைப் பயன்படுத்தவும்.',
'Customers_with_login_alert' => 'இந்த வாடிக்கையாளர்களுக்கு ஆன்லைன் கடைக் கணக்கு உள்ளது, அவர்கள் உங்கள் கடையில் உள்நுழையலாம். இங்கே செய்யப்படும் மாற்றங்கள் (மின்னஞ்சல், கடவுச்சொல், நிலை, தடுப்பு) அவர்களின் ஆன்லைன் கடை உள்நுழைவை மட்டுமே பாதிக்கும் - POS வாடிக்கையாளர் பதிவை அல்ல.',
