'Resize_Product_Images_Help' => 'பொருள், வகை மாறுபாடு மற்றும் கேலரி படங்கள் சேமிக்கப்படும்போது அவற்றின் அளவைக் குறைக்கவும். பதிவேற்றிய கோப்புகளை அவற்றின் அசல் தெளிவுத்திறனில் சேமிக்க இதை முடக்கவும் (பெரிய கோப்புகள், மெதுவான பக்கங்கள்).',
