'Product_Image_Max_Size_Help' => 'சேமிக்கப்படும் பொருள் படங்கள் பொருத்தப்படும் மிக நீண்ட பக்கம், பிக்சல்களில். விகிதம் பாதுகாக்கப்படும், சிறிய படங்கள் ஒருபோதும் பெரிதாக்கப்படாது.',
'Grid_View' => 'அட்டைகள்',
'Table_View' => 'அட்டவணை',
'Image_Max_2MB' => 'படம் 2 MB அல்லது அதற்குக் குறைவாக இருக்க வேண்டும்.',
'Units_Guide_Title' => 'அலகுகள் எவ்வாறு செயல்படுகின்றன',
'Units_Guide_Base' => 'அடிப்படை அலகு: "அடிப்படை அலகு" புலத்தைக் காலியாக விடவும். சரக்கு எப்போதும் இந்த அலகில் எண்ணப்படும், எடுத்துக்காட்டாக துண்டு.',
'Units_Guide_Sub' => 'துணை அலகு: ஒரு "அடிப்படை அலகைத்" தேர்வுசெய்து, அதை அந்த அடிப்படை அலகாக மாற்ற "ஆபரேட்டர்" மற்றும் "செயல்பாட்டு மதிப்பு" ஆகியவற்றைப் பயன்படுத்தவும்.',
'Units_Guide_Example_Multiply' => 'எடுத்துக்காட்டு: அடிப்படை அலகு துண்டு, ஆபரேட்டர் * மற்றும் மதிப்பு 12 உடன் ஒரு பெட்டி. 1 பெட்டியை விற்றால் சரக்கிலிருந்து 12 துண்டுகள் கழிக்கப்படும்.',
'Units_Guide_Example_Divide' => 'எடுத்துக்காட்டு: அடிப்படை அலகு கிலோகிராம், ஆபரேட்டர் / மற்றும் மதிப்பு 1000 உடன் ஒரு கிராம். 500 கிராம் விற்றால் சரக்கிலிருந்து 0.5 கிலோகிராம் கழிக்கப்படும்.',
'Units_Guide_Note' => 'அடிப்படை அலகுகளை மட்டுமே "அடிப்படை அலகாகத்" தேர்வுசெய்ய முடியும், மேலும் துணை அலகுகள் பயன்படுத்தும் வரை ஒரு அலகை நீக்க முடியாது.',
'Amount_Paid' => 'செலுத்திய தொகை',
'Payment_Amounts_Help' => 'செலுத்திய தொகை இருப்பைத் தீர்த்து நிலுவையைக் குறைக்கிறது. பெறப்பட்ட தொகை என்பது வழங்கப்பட்ட ரொக்கம்: திருப்பித் தர வேண்டிய மீதியைக் கணக்கிட மட்டுமே பயன்படும், நிலுவையை மாற்றாது.',
'Show_Tax_Desc' => 'செக்அவுட்டில் முழு விற்பனைக்கும் பயன்படுத்தப்படும் வரி, மொத்தங்களில் தனி "ஆர்டர் வரி" வரியாக அச்சிடப்படும்.',
'Show_Items_Tax_Desc' => 'ஒவ்வொரு பொருளின் சொந்த வரியின் கூட்டுத்தொகை, "மொத்தப் பொருட்கள் வரி" வரியாக அச்சிடப்படும். இயக்கப்பட்டால், துணைமொத்தம் இந்த வரிகள் நீங்கலாகக் காட்டப்படும்.',
'Show_Discount_Desc' => 'முழு விற்பனைக்கும் பயன்படுத்தப்படும் தள்ளுபடி (புள்ளித் தள்ளுபடி உட்பட), மொத்தங்களில் தனி வரியாக அச்சிடப்படும்.',
'Show_Product_Discount_Desc' => 'ஒவ்வொரு பொருளின் சொந்தத் தள்ளுபடி, பொருட்கள் பட்டியலில் அந்தப் பொருளின் கீழ் அச்சிடப்படும்.',
'Receipt_Font_Family' => 'ரசீது எழுத்துரு',
'Receipt_Font_Family_Desc' => 'அச்சிடப்பட்ட ரசீதில் உள்ள அனைத்து உரைக்கும் பயன்படுத்தப்படும் எழுத்துரு. "இயல்பு" நிலையான ரசீது எழுத்துருக்களை வைத்திருக்கும்.',
'Receipt_Font_Size' => 'ரசீது எழுத்துரு அளவு (px)',
'Receipt_Font_Size_Desc' => 'முழு ரசீதிலும் உரை அளவு, 8 முதல் 24 பிக்சல்கள் வரை. இயல்பு அளவை வைத்திருக்கக் காலியாக விடவும்.',
'Font_Default' => 'இயல்பு',
'Amount_Paid_Help' => 'இந்த ஆவணத்திற்குப் பயன்படுத்தப்படும் தொகை; இது மீதமுள்ள நிலுவையைக் குறைக்கிறது.',
'Received_Amount_Help' => 'உண்மையில் வழங்கப்பட்ட ரொக்கம். செலுத்திய தொகைக்கு மேல் உள்ள எதுவும் மீதியாகத் திருப்பித் தரப்படும், நிலுவையைக் குறைக்காது.',
'OpeningBalanceReceived' => 'பெறப்பட்ட தொடக்க இருப்பு',
'OpeningBalancePaid' => 'செலுத்திய தொடக்க இருப்பு',
'Customize_Profit' => 'லாபத்தைத் தனிப்பயனாக்கு',
'Custom_Profit' => 'தனிப்பயன் லாபம்',
'Custom_Profit_Hint' => 'உங்கள் சொந்த லாப எண்ணிக்கையை உருவாக்க எந்தத் தொகைகள் கூட்டப்பட வேண்டும் அல்லது கழிக்கப்பட வேண்டும் என்பதைத் தேர்வுசெய்யவும். உங்கள் தேர்வு இந்தச் சாதனத்தில் சேமிக்கப்படும்.',
'Profit_Formula' => 'லாபச் சூத்திரம்',
'Income_Statement' => 'வருமான அறிக்கை',
