'Taxes_Paid' => 'செலுத்திய வரிகள் (கொள்முதல்கள்)',
'Discounts_Given' => 'வழங்கிய தள்ளுபடிகள் (விற்பனைகள்)',
'Discounts_Received' => 'பெற்ற தள்ளுபடிகள் (கொள்முதல்கள்)',
'Shipping_Charged' => 'வசூலித்த அனுப்புதல் கட்டணம் (விற்பனைகள்)',
'Shipping_Paid' => 'செலுத்திய அனுப்புதல் கட்டணம் (கொள்முதல்கள்)',
'Expenses_By_Category' => 'வகையின்படி செலவுகள்',
'Daily_Trend' => 'தினசரிப் போக்கு',
'Additional_Information' => 'கூடுதல் தகவல்',
'Warehouses_Tab_Help' => 'உங்கள் கிடங்குகளை (கடைகள்/கிளைகள்) நிர்வகிக்கவும். ஒவ்வொரு கிடங்கும் தனது சொந்தச் சரக்கை வைத்திருக்கும், மேலும் ஒவ்வொரு ஆவணமும் — விற்பனைகள், கொள்முதல்கள், பரிமாற்றங்கள், சரிசெய்தல்கள் — அவற்றில் ஒன்றின் கீழ் பதிவுசெய்யப்படும்.',
'Warehouse_Locations_Tab_Help' => 'ஒவ்வொரு கிடங்கிற்குள்ளும் ரேக் / அலமாரி இடங்களை வரையறுக்கவும் (எ.கா. Aisle 2 – Rack B). பொருட்கள் உண்மையில் எங்கே சேமிக்கப்பட்டுள்ளன என்பதைக் காட்ட அவற்றைப் பொருட்களுக்கு ஒதுக்கவும்.',
'Already_Converted' => 'விற்பனையாக மாற்றப்பட்டது',
'Salesperson' => 'விற்பனையாளர்',
'Select_Salesperson' => 'விற்பனையாளரைத் தேர்வுசெய்க',
'You' => 'நீங்கள்',
'Enable_Pos_Salesperson_Switch' => 'செக்அவுட்டின்போது விற்பனையாளரை மாற்று',
'Enable_Pos_Salesperson_Switch_Hint' => 'வெளியேறாமலேயே ஒரு விற்பனையை மற்றொரு ஊழியருக்குக் காரணமாக்க, POS திரையில் விற்பனையாளர் தேர்வியைக் காட்டவும். தேர்வுசெய்யப்பட்ட விற்பனையாளர் விலைப்பட்டியலில் சேமிக்கப்பட்டு விற்பனை அறிக்கைகளில் பயன்படுத்தப்படும்; செயலில் உள்ள POS அமர்வு மாறாது.',
'Wallet_Payment_Method_Missing' => 'Wallet கட்டண முறை இல்லை',
'Wallet_Payment_Method_Missing_Help' => '"Wallet" என்ற சரியான பெயருடன் கட்டண முறை எதுவும் கிடைக்கவில்லை. POS wallet கட்டணம் இந்தப் பெயரால் பொருத்தப்படுகிறது, எனவே நீங்கள் "Wallet" என்ற பெயரில் ஒரு கட்டண முறையை இங்கே சேர்க்கும் வரை வாடிக்கையாளர்கள் தங்கள் wallet மூலம் செலுத்த முடியாது:',
'Show_Previous_Dues_Line' => 'முந்தைய நிலுவை வரியைக் காட்டு',
'Show_Previous_Dues_Line_Desc' => 'இந்த விற்பனைக்கு முன் வாடிக்கையாளர் செலுத்த வேண்டியிருந்த இருப்பு. பூஜ்ஜியத்தை விட அதிகமாக இருக்கும்போது மட்டுமே அச்சிடப்படும்.',
'Show_Net_Balance_Line' => 'நிகர இருப்பு வரியைக் காட்டு',
'Show_Net_Balance_Line_Desc' => 'முந்தைய நிலுவைகளுடன் இந்த விற்பனையில் இன்னும் நிலுவையில் உள்ளது. முந்தைய நிலுவைகள் பூஜ்ஜியத்தை விட அதிகமாக இருக்கும்போது மட்டுமே அச்சிடப்படும்.',
'QZ_Tray_Printer' => 'QZ Tray (இந்தக் கணினியில் உள்ள அச்சுப்பொறி)',
'QZ_Printer_Name_Hint' => 'QZ Tray இயங்கும் கணினியில் தோன்றும் அச்சுப்பொறியின் பெயர். அந்தக் கணினியின் இயல்பு அச்சுப்பொறியைப் பயன்படுத்தக் காலியாக விடவும். அச்சுப்பொறிகளைக் கண்டறிய ⟳ கிளிக் செய்யவும்.',
'QZ_Not_Running' => 'இந்தக் கணினியில் QZ Tray இயங்கவில்லை. qz.io இலிருந்து நிறுவி இயங்க வைத்திருங்கள், பின்னர் QZ கேட்கும்போது இந்த இணையதளத்தை அனுமதிக்கவும்.',
'Detect_Printers' => 'அச்சுப்பொறிகளைக் கண்டறி',
'QZ_Download_Cert' => 'சான்றிதழைப் பதிவிறக்கு (override.crt)',
'QZ_Setup_Title' => 'QZ Tray அச்சிடுதலை எவ்வாறு அமைப்பது (ஒருமுறை, லேபிள்களை அச்சிடும் ஒவ்வொரு கணினியிலும்)',
'QZ_Step_Install' => '1. இந்தக் கணினியில் QZ Tray-ஐ நிறுவவும் — qz.io இலிருந்து இலவசமாகப் பதிவிறக்கி, தொடங்கி இயங்க விடவும் (இது Windows-இல் system tray-இலும் macOS-இல் menu bar-இலும் இருக்கும்).',
'QZ_Step_Connect' => '2. உங்கள் லேபிள் அச்சுப்பொறியை USB மூலம் இணைத்து, அது இயக்க முறைமையில் நிறுவப்பட்டுள்ளதா எனச் சரிபார்க்கவும் (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. இந்தக் கணினியில் உள்ள அச்சுப்பொறிகளைக் கண்டறிய மேலே உள்ள "அச்சுப்பொறியின் பெயர்" அருகில் உள்ள ⟳ பொத்தானைக் கிளிக் செய்து, உங்கள் லேபிள் அச்சுப்பொறியைத் தேர்வுசெய்யவும். கணினியின் இயல்பு அச்சுப்பொறியைப் பயன்படுத்தப் புலத்தைக் காலியாக விடவும்.',
'QZ_Step_Cert' => '4. அனுமதி பாப்அப் இல்லாமல் அச்சிட, கீழே உள்ள சான்றிதழைப் பதிவிறக்கி, override.crt எனப் பெயர் மாற்றி QZ Tray நிறுவல் கோப்புறையில் நகலெடுக்கவும் (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). பின்னர் QZ Tray-ஐ மூடி மீண்டும் தொடங்கவும்.',
'QZ_Step_Test' => '5. கீழே உள்ள "சோதனை லேபிளை அச்சிடு" என்பதைக் கிளிக் செய்யவும். QZ Tray அனுமதி கேட்டால், Allow என்பதைக் கிளிக் செய்யவும் — சான்றிதழ் நிறுவப்பட்டிருந்தால் மீண்டும் கேட்காது.',
'QZ_Step_Save' => '6. இந்த அமைப்புகளைச் சேமிக்கச் சமர்ப்பி என்பதைக் கிளிக் செய்யவும். பார்கோடு அச்சிடு பக்கத்திலிருந்து லேபிள்கள் இனி உலாவி அச்சு உரையாடல் இல்லாமல் நேரடியாக இந்த அச்சுப்பொறியில் அச்சிடப்படும்.',
'QZ_Setup_Note' => 'QZ Tray நீங்கள் உலாவும் கணினியில் இயங்குகிறது, எனவே Stocky தொலைநிலைச் சேவையகத்தில் ஹோஸ்ட் செய்யப்பட்டிருந்தாலும் இது வேலை செய்யும். லேபிள்களை அச்சிடும் ஒவ்வொரு கணினியிலும் QZ Tray நிறுவப்பட வேண்டும்.',
'PWA_Enabled' => 'நிறுவக்கூடிய பயன்பாட்டை இயக்கு',
'PWA_Enabled_Help' => 'போன்கள், டேப்லெட்டுகள் மற்றும் டெஸ்க்டாப்களில் இந்தப் பயன்பாட்டை நிறுவ உலாவிகள் வழங்க அனுமதிக்கிறது, மேலும் ஆஃப்லைனில் வேலை செய்யும் பக்கங்களை கேஷில் வைத்திருக்கிறது. இதை முடக்கினால் எல்லா இடங்களிலும் நிறுவல் அறிவுறுத்தல் நீக்கப்பட்டு, அடுத்த வருகையில் கேஷ் அழிக்கப்படும்.',
'PWA_Identity' => 'பயன்பாட்டு அடையாளம்',
'PWA_Launch' => 'தொடக்கம் மற்றும் தோற்றம்',
'PWA_App_Name' => 'பயன்பாட்டின் பெயர்',
'PWA_App_Name_Help' => 'நிறுவல் அறிவுறுத்தலிலும் பயன்பாட்டுப் பட்டியலிலும் காட்டப்படும். தோற்ற அமைப்புகளில் உள்ள பயன்பாட்டுப் பெயரைப் பயன்படுத்தக் காலியாக விடவும்.',
'PWA_Short_Name' => 'சுருக்கப் பெயர்',
'PWA_Short_Name_Help' => 'நீண்ட பெயர்கள் வெட்டப்படும் முகப்புத் திரைகளில் ஐகானின் கீழ் காட்டப்படும். பயன்பாட்டுப் பெயரில் "|"-க்கு முந்தைய பகுதியைப் பயன்படுத்தக் காலியாக விடவும்.',
'PWA_Description' => 'விளக்கம்',
'PWA_Description_Help' => 'சில பயன்பாட்டுக் கடைகள் மற்றும் நிறுவல் உரையாடல்களில் காட்டப்படும்.',
'PWA_Start_Url' => 'தொடக்கப் பக்கம்',
'PWA_Start_Url_Help' => 'நிறுவப்பட்ட பயன்பாடு திறக்கும் பக்கம், "/" உடன் தொடங்கும் பாதையாக. நேரடியாக POS-இல் தொடங்க /next/pos பயன்படுத்தவும்.',
'PWA_Display_Mode' => 'காட்சிப் பயன்முறை',
'PWA_Display_Mode_Help' => 'standalone உலாவிப் பட்டியை மறைக்கும்; fullscreen நிலைப் பட்டியையும் மறைக்கும்; browser சாதாரண தாவலைத் திறக்கும்.',
'PWA_Orientation' => 'திசையமைவு',
'PWA_Theme_Color' => 'தீம் நிறம்',
'PWA_Theme_Color_Help' => 'நிறுவப்பட்ட பயன்பாட்டைச் சுற்றியுள்ள கணினிப் பட்டிகளுக்கு நிறமிடும்.',
'PWA_Background_Color' => 'ஸ்பிளாஷ் பின்னணி',
'PWA_Background_Color_Help' => 'பயன்பாடு தொடங்கும்போது காட்டப்படும் ஸ்பிளாஷ் திரையின் பின்னணி.',
'PWA_Preview' => 'முன்னோட்டம்',
'PWA_View_Manifest' => 'manifest கோப்பைக் காண்க',
'PWA_Reinstall_Notice' => 'ஏற்கனவே பயன்பாட்டை நிறுவிய சாதனங்கள், அது நீக்கப்பட்டு மீண்டும் நிறுவப்படும் வரை பழைய பெயர் மற்றும் ஐகானை வைத்திருக்கும்.',
'Label_Render_Mode' => 'லேபிள் வரைதல்',
'Label_Render_Mode_Hint' => 'லேபிள் எவ்வாறு வரையப்படுகிறது. அச்சுப்பொறி எழுத்துருக்கள் மிக வேகமானவை, மிகக் கூர்மையான பார்கோடைத் தரும், ஆனால் அச்சுப்பொறியின் சொந்த எழுத்துருவில் அடிப்படை லத்தீன் எழுத்துகளை மட்டுமே அச்சிடும். முன்னோட்டப் படம் உங்கள் லேபிள் வடிவமைப்பை — நீங்கள் தேர்ந்தெடுத்த எழுத்துரு, எந்த மொழியிலும் — பிரத்யேக லேபிள் மென்பொருள் செய்வது போலவே சரியாக மீளுருவாக்கும்.',
'Render_Native' => 'அச்சுப்பொறி எழுத்துருக்கள் (மிக வேகமானது)',
'Render_Raster' => 'முன்னோட்டப் படம் (சரியான வடிவமைப்பு)',
'Label_Width_Mm' => 'லேபிள் அகலம் (mm)',
'Label_Height_Mm' => 'லேபிள் உயரம் (mm)',
'Label_Size_Hint' => 'ரோலில் உள்ள ஒரு ஸ்டிக்கரின் உண்மையான அளவு. இது ஏற்றப்பட்ட லேபிள்களுடன் சரியாகப் பொருந்த வேண்டும் — தவறான அளவு அச்சுப்பொறியைத் தவறான இடத்தில் இடைவெளியைத் தேடச் செய்யும், இதனால் ஒவ்வொரு லேபிளும் மேலும் விலகி அச்சிடப்படும்.',
'Calibrate_Labels' => 'லேபிள்களை அளவுத்திருத்து',
'Calibrate_Labels_Hint' => 'ஸ்டிக்கர் மற்றும் இடைவெளியை அளக்க அச்சுப்பொறி சில லேபிள்களை முன்னோக்கி நகர்த்தும். புதிய ரோலை ஏற்றிய பிறகு அல்லது அச்சு நிலைகள் விலகும்போது ஒருமுறை இயக்கவும்.',
'Calibration_Sent' => 'அளவுத்திருத்தம் தொடங்கியது — அளக்க அச்சுப்பொறி சில வெற்று லேபிள்களை நகர்த்தும். அது நின்றதும், சோதனை அச்சை இயக்கவும்.',
'Label_Printer_Dpi' => 'அச்சுத்தலை தெளிவுத்திறன்',
'Label_Printer_Dpi_Hint' => 'பெரும்பாலான லேபிள் அச்சுப்பொறிகள் 203 dpi. உறுதியாகத் தெரியவில்லையா? கீழே உள்ள "தெளிவுத்திறனைக் கண்டறி" பொத்தானைப் பயன்படுத்தவும் — அது பதிலை அச்சிடும்.',
'Find_Resolution' => 'தெளிவுத்திறனைக் கண்டறி',
'Find_Resolution_Hint' => '203 மற்றும் 300 எனக் குறிக்கப்பட்ட இரண்டு லேபிள்களை அச்சிடும். சரியானது ஸ்டிக்கரில் நான்கு பக்கங்களிலும் சிறிய சீரான ஓரத்துடன் முழுமையான செவ்வகத்தைக் காட்டும்; தவறானதில் எல்லைகள் விடுபட்டிருக்கும் அல்லது அடுத்த ஸ்டிக்கருக்குள் நீளும்.',
'Dpi_Test_Sent' => '203 மற்றும் 300 எனக் குறிக்கப்பட்ட இரண்டு லேபிள்கள் அச்சிடப்படுகின்றன. சரியானது நான்கு பக்கங்களிலும் சிறிய, சீரான ஓரத்துடன் முழுமையான செவ்வகத்தைக் காட்டும் — "அச்சுத்தலை தெளிவுத்திறன்" என்பதை அந்த எண்ணாக அமைத்துச் சேமிக்கவும்.',
'Label_Offset_X' => 'கிடைமட்ட விலகல் (mm)',
'Label_Offset_X_Hint' => 'ஸ்டிக்கரில் அச்சைப் பக்கவாட்டில் நகர்த்தும். ஒரு பக்க ஓரத்தில் உரை வெட்டப்படும்போது பயன்படுத்தவும் — எ.கா. வெள்ளை ஸ்டிக்கர் அகலமான பின்தாளின் மையத்தில் இருக்கும்போது 2.5. 0.5 படிகளில் சரிசெய்யவும்.',
'Label_Offset_Y' => 'செங்குத்து விலகல் (mm)',
'Label_Offset_Y_Hint' => 'லேபிளின் நீளவாக்கில் அச்சை நகர்த்தும். வடிவமைப்பின் மேல்பகுதி வெட்டப்பட்டால் அல்லது விடுபட்டால் அதிகரிக்கவும்; அது மிகக் கீழே தொடங்கினால் குறைக்கவும்.',
'Feed_To_Tear' => 'கிழிக்கும் விளிம்பிற்கு நகர்த்து',
'Feed_To_Tear_Hint' => 'ஒவ்வொரு பணிக்குப் பிறகும் லேபிளைக் கிழிக்கும் பட்டி வரை நகர்த்தும். லேபிள்கள் கீழ்நோக்கி நகர்ந்து அச்சிடப்பட்டால் அல்லது ஸ்டிக்கர்களுக்கு இடையே பிரிந்தால் இதை முடக்கியே வைக்கவும் — பல அச்சுப்பொறிகள் அடுத்த லேபிளுக்கு முன் பின்னோக்கித் திரும்புவதில்லை.',
'Install_App' => 'பயன்பாட்டை நிறுவு',
'pos.Cart_Restored' => 'உங்கள் கார்ட் மீட்டெடுக்கப்பட்டது',
'pos.Draft_Saved_Offline' => 'வரைவு ஆஃப்லைனில் சேமிக்கப்பட்டது. நீங்கள் மீண்டும் ஆன்லைனில் வந்ததும் ஒத்திசைக்கப்படும்.',
'pos.Client_Saved_Offline' => 'வாடிக்கையாளர் ஆஃப்லைனில் சேமிக்கப்பட்டார். நீங்கள் மீண்டும் ஆன்லைனில் வந்ததும் ஒத்திசைக்கப்படும்.',
'Mobile_App_Settings' => 'மொபைல் பயன்பாடு',
'Mobile_App_Settings_Help' => 'Stocky மொபைல் பயன்பாட்டைக் கட்டுப்படுத்தவும்: அதை இயக்கவும் அல்லது முடக்கவும், அதன் பெயர், லோகோ மற்றும் நிறத்தை அமைக்கவும், உங்கள் குழு எந்தத் தொகுதிகளைக் காண வேண்டும் என்பதைத் தேர்வுசெய்யவும்.',
'Mobile_App_Enabled' => 'மொபைல் பயன்பாடு இயக்கப்பட்டது',
'Mobile_App_Enabled_Help' => 'முடக்கப்பட்டால், யாரும் மொபைல் பயன்பாட்டிலிருந்து உள்நுழைய முடியாது, அதற்குப் பதிலாகக் கீழே உள்ள செய்தி காட்டப்படும்.',
'Mobile_App_Disabled_Notice' => 'மொபைல் பயன்பாடு தற்போது முடக்கப்பட்டுள்ளது.',
