'Upload_Then_Validate_Hint' => 'புதுப்பிப்புக்கு முந்தைய சோதனைகளை இயக்க ஒரு புதுப்பிப்புத் தொகுப்பைப் பதிவேற்றவும்: ZIP ஒருமைப்பாடு, தொகுப்புக் கட்டமைப்பு, பதிப்பு இணக்கம், PHP தேவைகள், அனுமதிகள், வட்டு இடம், தரவுத்தள இணைப்பு மற்றும் பல.',
