'Backups_Stored_Hint' => 'காப்புப்பிரதிகள் storage/app/updater/backups-இல் சேமிக்கப்படுகின்றன, அவை ஒருபோதும் இணையம் வழியாக அணுக முடியாதவை. மீதமுள்ள ஒரே முழுமையான காப்புப்பிரதியை ஒருபோதும் நீக்க முடியாது.',
