'Start_Update_Confirm_Text' => 'கணினி அனைத்து கோப்புகளையும் தரவுத்தளத்தையும் காப்புப்பிரதி எடுத்து, பராமரிப்புப் பயன்முறையை இயக்கி, புதிய பதிப்பை நிறுவும். ஏதேனும் தோல்வியடைந்தால், முந்தைய பதிப்பு தானாக மீட்டெடுக்கப்படும். தொடரவா?',
'Update_Connection_Lost' => 'சேவையகத்துடனான இணைப்பு துண்டிக்கப்பட்டது. புதுப்பிப்பு பாதுகாப்பாக உள்ளது — தொடர அல்லது திரும்பப் பெற இந்தப் பக்கத்தை (அல்லது மீட்பு கன்சோலை) மீண்டும் திறக்கவும்.',
'Rollback_Confirm_Text' => 'முந்தைய பதிப்புக்குத் திரும்பவா? கோப்புகளும் தரவுத்தளமும் புதுப்பிப்புக்கு முந்தைய காப்புப்பிரதியிலிருந்து மீட்டெடுக்கப்படும்.',
'Restore_Backup_Confirm_Text' => 'இந்தக் காப்புப்பிரதியை மீட்டெடுக்கவா? தற்போதைய கோப்புகளும் தற்போதைய தரவுத்தளமும் காப்புப்பிரதியால் மாற்றப்படும். முதலில் தற்போதைய தரவுத்தளத்தின் பாதுகாப்பு நகல் எடுக்கப்படும்.',
'Delete_Backup_Confirm_Text' => 'இந்தக் காப்புப்பிரதியை நிரந்தரமாக நீக்கவா? இதைச் செயல்தவிர்க்க முடியாது.',
