'No_maximum' => 'அதிகபட்சம் இல்லை',
'Whole_country' => 'முழு நாடு',
'Shipping_Zone_Locations_Help' => 'வேறு எந்த மண்டலமும் பொருந்தாதபோது பயன்படுத்தப்படும் பொது மண்டலத்திற்கு டிக் செய்யவும், அல்லது அது உள்ளடக்கும் நாடுகளை (விருப்பமாக மாநிலங்களையும்) பட்டியலிடவும்.',
'Shipping_Zone_Delete_Warning' => 'மண்டலம் அகற்றப்பட்டு அதன் விதிகள் செயலிழக்கப்படும். ஏற்கனவே உள்ள ஆர்டர்கள் தங்கள் அனுப்புதல் விவரங்களை வைத்திருக்கும்.',
'Free_delivery' => 'இலவச டெலிவரி',
'Estimated_Delivery_Date' => 'மதிப்பிடப்பட்ட டெலிவரி தேதி',
'Estimated_Delivery_Date_Hint' => 'பொருள் அட்டை மற்றும் பொருள் பக்கத்தில் வாங்குபவர்களுக்கு "மதிப்பிடப்பட்ட டெலிவரி" எனக் காட்டப்படும். எதையும் காட்டாமல் இருக்கக் காலியாக விடவும். முன்கூட்டிய ஆர்டர் பொருளுக்கு, இது கிடைக்கத் தொடங்கும் தேதியும் ஆகும்.',
'Preorder_Uses_Delivery_Date' => 'கிடைக்கும்தன்மை மேலே உள்ள கடைப் பிரிவில் அமைக்கப்பட்ட மதிப்பிடப்பட்ட டெலிவரி தேதியைப் பயன்படுத்துகிறது.',
'Related_Products' => 'தொடர்புடைய பொருட்கள்',
'Related_Products_Hint' => 'இந்தப் பொருள் பக்கத்தில் "தொடர்புடைய பொருட்கள்" பகுதியில் காட்டப்படும் பொருட்களை வரிசைப்படி தேர்வுசெய்யவும். தானியங்கு விதியைப் (அதே வகை, பின்னர் புதியவை) பயன்படுத்தக் காலியாக விடவும்.',
'Enable_Wholesale_Pricing' => 'அளவின்படி மொத்த விற்பனை விலை',
'Enable_Wholesale_Pricing_Hint' => 'ஆர்டர் செய்யப்பட்ட அளவு ஒரு அடுக்கை அடைந்ததும் POS மற்றும் ஆன்லைன் கடையில் சில்லறை விலையைத் தானாக மாற்றும் அளவு இடைவெளிகளை (10-19 pcs, 20-49 pcs, 100+ ...) பொருட்களுக்கு அமைக்க அனுமதிக்கவும். இதை முடக்கினால் அனைத்தும் மீண்டும் சாதாரண சில்லறை விலையில் விற்கப்படும் — கட்டமைக்கப்பட்ட அடுக்குகள் வைக்கப்படும், ஆனால் பயன்படுத்தப்படாது.',
'Wholesale_Pricing_By_Quantity' => 'அளவின்படி மொத்த விற்பனை விலை',
'Wholesale_Pricing_By_Quantity_Hint' => 'ஆர்டர் செய்யப்பட்ட அளவு ஒரு அடுக்கை அடைந்ததும் ஒரு துண்டுக்கான விலை. திறந்த மேல் அடுக்கிற்கு அதிகபட்சத்தைக் காலியாக விடவும் (எ.கா. 100 மற்றும் அதற்கு மேல்). முதல் அடுக்கிற்குக் கீழே பொருள் அதன் சாதாரண சில்லறை விலையில் விற்கப்படும்.',
'Wholesale_Pricing_Variants_Hint' => 'ஒரே ஏணி முழுப் பொருளுக்கும் பொருந்தும்: ஒவ்வொரு வகை மாறுபாடும் அதன் சொந்த வரி ஒரு அடுக்கை அடைந்ததும் அடுக்கு விலையில் விற்கப்படும்.',
'Min_Quantity' => 'குறைந்தபட்ச அளவு',
'Max_Quantity' => 'அதிகபட்ச அளவு',
'Price_Per_Piece' => 'ஒரு துண்டுக்கான விலை',
'Wholesale' => 'மொத்த விற்பனை',
'Wholesale_Tier_Applied' => 'இந்த வரிக்கு மொத்த விற்பனை அளவு அடுக்கு பொருந்தும்',
'Orders_Guide' => 'ஆர்டர்கள் வழிகாட்டி',
'Ord_Guide_Intro' => 'உங்கள் ஆன்லைன் கடையில் வைக்கப்படும் ஆர்டர் உங்கள் சரக்கு மற்றும் கணக்குகளுக்குள் எவ்வாறு செல்கிறது, பணம் உண்மையில் எங்கே பதிவுசெய்யப்படுகிறது.',
'Ord_Guide_Lifecycle_Title' => 'ஆர்டர் நிலை',
'Ord_Guide_Lifecycle_Pending' => 'உங்கள் மதிப்பாய்வுக்காகக் காத்திருக்கும் புதிய ஆர்டர். நிலுவையில் உள்ள ஆர்டரை மட்டுமே உறுதிப்படுத்தவோ ரத்து செய்யவோ முடியும்.',
'Ord_Guide_Lifecycle_Confirmed' => 'நீங்கள் ஆர்டரை ஏற்றுக்கொண்டீர்கள். நீங்கள் தேர்வுசெய்த கிடங்கில் Stocky ஒரு விற்பனையை உருவாக்கி சரக்கைக் கழிக்கும் — உங்கள் சரக்கு, கட்டணம் மற்றும் லாப அறிக்கைகள் படிக்கும் பதிவு அந்த விற்பனையே.',
'Ord_Guide_Lifecycle_Shipped' => 'நீங்கள் ஆர்டரை அனுப்பினீர்கள். நிறைவேற்றுதல் மட்டுமே: நீங்கள் உறுதிப்படுத்தியபோதே சரக்கு கழிக்கப்பட்டது.',
'Ord_Guide_Lifecycle_Delivered' => 'வாடிக்கையாளர் ஆர்டரைப் பெற்றார். இதுவே திருப்பக் காலத்தைத் தொடங்குகிறது.',
'Ord_Guide_Lifecycle_Cancelled' => 'உறுதிப்படுத்தலுக்கு முன்பே ஆர்டர் கைவிடப்பட்டது, எனவே விற்பனை எதுவும் உருவாக்கப்படவில்லை, சரக்கும் கழிக்கப்படவில்லை.',
'Ord_Guide_PaymentStatus_Tip' => 'செக்அவுட்டில் அமைக்கப்பட்டது, இங்கே திருத்த முடியாது. கட்டணத்தை எவ்வாறு பதிவுசெய்வது என்பதைக் காணக் கிளிக் செய்யவும்.',
'Ord_Guide_Payment_Title' => 'கட்டண நிலை',
'Ord_Guide_Payment_Intro' => 'இந்த நெடுவரிசை செக்அவுட்டில் வாடிக்கையாளர் எவ்வாறு செலுத்தத் தேர்வுசெய்தார் என்பதைப் பதிவுசெய்கிறது. இது கடையால் அமைக்கப்படுகிறது, இந்தப் பக்கத்திலிருந்து திருத்த முடியாது — பணம் ஆர்டரை உறுதிப்படுத்தும்போது உருவாகும் விற்பனையில் கண்காணிக்கப்படுகிறது.',
'Ord_Guide_Payment_Paid' => 'வாடிக்கையாளர் ஏற்கனவே கட்டண நுழைவாயில் மூலம் ஆன்லைனில் செலுத்திவிட்டார். ஆர்டரை உறுதிப்படுத்தினால் விற்பனை செலுத்தப்பட்டதாக உருவாக்கப்பட்டு உங்களுக்காகக் கட்டணம் பதிவுசெய்யப்படும் — வேறு எதுவும் செய்ய வேண்டியதில்லை.',
'Ord_Guide_Payment_Pending' => 'டெலிவரியின்போது பணம், வங்கிப் பரிமாற்றம் அல்லது பின்னர் செலுத்தும் மற்றொரு முறை. ஆர்டரை உறுதிப்படுத்தினால் விற்பனை செலுத்தப்படாததாக உருவாக்கப்படும், எனவே பணத்தை வசூலித்ததும் நீங்களே பதிவுசெய்ய வேண்டும் — கீழே உள்ள படிகளைப் பார்க்கவும்.',
'Ord_Guide_Payment_Failed' => 'நுழைவாயில் கட்டணத்தை நிராகரித்தது அல்லது வாடிக்கையாளர் அதைக் கைவிட்டார். ஆர்டர் தானாக ரத்து செய்யப்படும்.',
'Ord_Guide_MarkPaid_Title' => 'கட்டணத்தை நிலுவையிலிருந்து செலுத்தப்பட்டதாக மாற்றுதல்',
'Ord_Guide_MarkPaid_Step1' => 'முதலில் இங்கே ஆர்டரை உறுதிப்படுத்தவும் — உறுதிப்படுத்துவதே விற்பனையை உருவாக்குகிறது.',
'Ord_Guide_MarkPaid_Step2' => 'விற்பனைகள் > அனைத்து விற்பனைகள் என்பதைத் திறந்து அந்த விற்பனையைக் கண்டறியவும் (அதே வாடிக்கையாளர், விவரங்கள் பக்கம் அது வந்த ஆன்லைன் ஆர்டரைக் காட்டும்).',
'Ord_Guide_MarkPaid_Step3' => 'வரிசைச் செயல்கள் மெனுவைத் திறந்து கட்டணத்தை உருவாக்கு என்பதைத் தேர்வுசெய்யவும்.',
'Ord_Guide_MarkPaid_Step4' => 'தொகை, கட்டண முறை மற்றும் தேதியை உள்ளிட்டுச் சேமிக்கவும். தொகையைப் பொறுத்து விற்பனை தானாகப் பகுதி அல்லது செலுத்தப்பட்டது நிலைக்கு மாறும்.',
'Ord_Guide_MarkPaid_Note' => 'இங்கே காட்டப்படும் கட்டண நிலை செக்அவுட் தேர்வைத் தொடர்ந்து பதிவுசெய்து அப்படியே இருக்கும். விற்பனையே கணக்கியல் பதிவு, அதுவே உங்கள் கட்டண மற்றும் லாப அறிக்கைகளுக்குத் தரவளிக்கிறது. நீங்கள் உள்ளிட்டதை மதிப்பாய்வு செய்ய அல்லது திருத்த விற்பனையில் கட்டணங்களைக் காட்டு என்பதைப் பயன்படுத்தவும்.',
'Ord_Guide_Notes_Title' => 'தெரிந்துகொள்ள வேண்டியவை',
'Ord_Guide_Note_Warehouse' => 'உறுதிப்படுத்தும்போது நீங்கள் தேர்வுசெய்யும் கிடங்கே சரக்கு எங்கிருந்து எடுக்கப்படும் என்பதைத் தீர்மானிக்கிறது. முழு ஆர்டரையும் பூர்த்தி செய்ய முடியாத கிடங்குகள் அந்தப் பட்டியலில் சரக்கில் இல்லை எனக் குறிக்கப்படும்.',
'Ord_Guide_Note_Preorder' => 'முன்கூட்டிய ஆர்டர் பொருட்கள் சரக்குச் சரிபார்ப்பைத் தவிர்க்கின்றன, எனவே அவற்றைக் கொண்ட ஆர்டரை அளவு கையிருப்பில் இல்லாதபோதும் உறுதிப்படுத்தலாம்.',
'Ord_Guide_Note_Flagged' => 'குறியிடப்பட்டது என்ற குறிச்சொல் செக்அவுட்டில் ஆர்டர் மோசடிச் சோதனையில் சிக்கியது என்பதைக் குறிக்கிறது. காரணத்தைக் காணக் குறிச்சொல்லின் மீது சுட்டியை வைத்து, உறுதிப்படுத்தும் முன் ஆர்டரை மதிப்பாய்வு செய்யவும்.',
'Ord_Guide_Note_Cancel' => 'ஆர்டர் நிலுவையில் இருக்கும்போது மட்டுமே ரத்து செய்ய முடியும். உறுதிப்படுத்தப்பட்டதும், அதற்குப் பதிலாக விற்பனை அல்லது வாடிக்கையாளர் திருப்பம் மூலம் மாற்றியமைக்கவும்.',
'CollectAtBranch' => 'கிளையில் பெற்றுக்கொள்',
'Pickup' => 'பெற்றுக்கொள்ளுதல்',
'ProofOfPayment' => 'கட்டணச் சான்று',
'ReferenceNumber' => 'குறிப்பு / பரிவர்த்தனை எண்',
'AmountSent' => 'அனுப்பிய தொகை',
'PaymentDate' => 'கட்டணத் தேதி',
'ProofAmountMismatchHint' => 'வாடிக்கையாளர் அனுப்பியதாகக் கூறும் தொகை ஆர்டர் மொத்தம் அல்ல.',
'AmountMismatch' => 'தொகை பொருந்தவில்லை',
'ViewFile' => 'கோப்பைக் காண்க',
'RejectProof' => 'கட்டணச் சான்றை நிராகரி',
'AwaitingVerification' => 'சரிபார்ப்புக்காகக் காத்திருக்கிறது',
'PaymentVerified' => 'கட்டணம் சரிபார்க்கப்பட்டது',
'ProofToVerify' => 'சரிபார்க்க வேண்டிய சான்று',
'GCash' => 'GCash',
'BankTransfer' => 'வங்கிப் பரிமாற்றம்',
'CashOnPickup' => 'பெற்றுக்கொள்ளும்போது ரொக்கம்',
