'OfflinePaymentsIntro' => 'கணினிக்கு வெளியே செலுத்தப்படும் அனைத்தும் இங்கே உள்ளன: டெலிவரியின்போது பணம், மொபைல் பணம், GCash, வங்கிப் பரிமாற்றம் மற்றும் பெற்றுக்கொள்ளும்போது ரொக்கம். நீங்கள் செலுத்தப்பட்டதாகக் குறிக்கும் வரை இந்த ஆர்டர்கள் கட்டண நிலுவையில் இருக்கும். GCash மற்றும் வங்கிப் பரிமாற்றம் வாடிக்கையாளரிடம் ஸ்கிரீன்ஷாட், குறிப்பு எண் மற்றும் தொகையைக் கேட்கும், அவற்றை நீங்கள் ஆர்டரில் அங்கீகரிப்பீர்கள்.',
