'Saved_Variants_Removed_On_Save' => 'இங்கே அகற்றப்பட்ட சேமித்த வகை மாறுபாடுகள் நீங்கள் பொருளைச் சேமிக்கும்போது நீக்கப்படும்.',
'Switch_To_List_Confirm' => 'எளிய பட்டியலுக்கு மாறவா? விருப்ப வரையறைகள் நீக்கப்படும்; வகை மாறுபாட்டு வரிசைகள் வைக்கப்படும்.',
'Style' => 'பாணி',
'Swatches' => 'வண்ண மாதிரிகள்',
'Guide' => 'வழிகாட்டி',
'Variants_Guide' => 'வகை மாறுபாடுகள் வழிகாட்டி',
'VG_Intro' => 'மாறுபடும் பொருள் பல வகை மாறுபாடுகளாக விற்கப்படுகிறது. அவற்றை விருப்பங்களிலிருந்து (பரிந்துரைக்கப்படுகிறது) அல்லது பெயர்களின் எளிய பட்டியலாக உருவாக்கவும். ஒவ்வொரு வகை மாறுபாட்டிற்கும் சொந்தக் குறியீடு, விலைகள், படம் மற்றும் சரக்கு உள்ளது.',
'VG_Options_Title' => 'விருப்பங்கள் பயன்முறை (நிறம், அளவு...)',
'VG_Opt_Step1' => 'அட்டைத் தலைப்பில் உள்ள சுவிட்சை "விருப்பங்கள்" என்பதிலேயே வைத்திருங்கள்.',
'VG_Opt_Step2' => 'நிறம் அல்லது அளவு போன்ற விருப்பப் பெயரைத் தட்டச்சு செய்யவும், அல்லது பரிந்துரைகளில் ஒன்றைத் தேர்வுசெய்யவும்.',
'VG_Opt_Step3' => 'ஒரு மதிப்பைத் (எடுத்துக்காட்டாக சிவப்பு) தட்டச்சு செய்து Enter அழுத்தவும். ஒவ்வொரு மதிப்புக்கும் மீண்டும் செய்யவும்; காற்புள்ளியும் மதிப்புகளைப் பிரிக்கும். ஒரு மதிப்பை அகற்ற அதன் மீதுள்ள x-ஐக் கிளிக் செய்யவும்.',
'VG_Opt_Step4' => 'இரண்டாவது அல்லது மூன்றாவது விருப்பத்திற்கு "விருப்பத்தைச் சேர்" என்பதைக் கிளிக் செய்யவும் (அதிகபட்சம் 3 விருப்பங்கள்).',
'VG_Opt_Step5' => '"வகை மாறுபாடுகளை உருவாக்கு" என்பதைக் கிளிக் செய்யவும். ஒவ்வொரு சேர்க்கைக்கும் ஒரு வரிசை உருவாக்கப்பட்டு அதன் பெயர் தானாக அமைக்கப்படும், எடுத்துக்காட்டாக "Red / S".',
'VG_Opt_Step6' => 'ஒவ்வொரு வரிசையிலும் செலவு மற்றும் விலையை உள்ளிடவும், அல்லது "அனைத்திற்கும் பயன்படுத்து" என்பதில் ஒரு மதிப்பைத் தட்டச்சு செய்து, அதை ஒவ்வொரு வரிசைக்கும் நகலெடுக்க செலவு அல்லது விலை என்பதைக் கிளிக் செய்யவும்.',
'VG_Opt_Step7' => 'குறியீடுகள் உங்களுக்காக உருவாக்கப்படும். உங்கள் சொந்தக் குறியீட்டைத் தட்டச்சு செய்யவும் அல்லது வேறொன்றை உருவாக்கப் புதுப்பிப்பு ஐகானைக் கிளிக் செய்யவும்.',
'VG_Opt_Step8' => 'விருப்பத்தேர்வு: ஒரு விருப்பத்தில் "வண்ண மாதிரிகள்" என்பதை டிக் செய்து ஒவ்வொரு மதிப்புக்கும் ஒரு நிறத்தைத் தேர்வுசெய்யவும்; கடை அதை வண்ணப் புள்ளியாகக் காட்டும்.',
'VG_Rows_Title' => 'வகை மாறுபாட்டு வரிசைகள்',
'VG_Rows_Text' => 'ஒவ்வொரு வரிசையிலும் படம், குறியீடு, பார்கோடு, செலவு, விலை, மொத்த விற்பனை விலை மற்றும் குறைந்தபட்ச விற்பனை விலை உள்ளன. பொருளை உருவாக்கும்போது ஒவ்வொரு வகை மாறுபாட்டிற்கும் கிடங்குவாரியான தொடக்கச் சரக்கையும் உள்ளிடலாம். "முழுமையடையவில்லை" குறிச்சொல் என்றால் வரிசையில் ஒரு விருப்பத்திற்கான மதிப்பு இல்லை.',
'VG_List_Title' => 'எளிய பட்டியல் பயன்முறை',
'VG_List_Text' => 'ஒரு வரிசையைச் சேர்க்க வகை மாறுபாட்டின் பெயரைத் தட்டச்சு செய்து Enter அழுத்தவும் (அல்லது சேர் என்பதைக் கிளிக் செய்யவும்), பின்னர் அதன் குறியீடு மற்றும் விலைகளை நிரப்பவும். இது பாரம்பரிய நடத்தை, ஏற்கனவே உள்ள பொருட்களுக்குத் தொடர்ந்து கிடைக்கும்.',
'VG_Edit_Title' => 'பின்னர் திருத்துதல்',
'VG_Edit_1' => 'ஒரு மதிப்பைச் சேர்த்து "வகை மாறுபாடுகளை உருவாக்கு" என்பதைக் கிளிக் செய்யவும்: விடுபட்ட சேர்க்கைகள் மட்டுமே சேர்க்கப்படும். ஏற்கனவே உள்ள வரிசைகள் தங்கள் குறியீடுகள், விலைகள் மற்றும் வரலாற்றை வைத்திருக்கும்.',
'VG_Edit_2' => 'ஒரு மதிப்பை அல்லது விருப்பத்தை அகற்றினால் அதைப் பயன்படுத்தும் வரிசைகள் அகற்றப்படும். ஏற்கனவே சேமிக்கப்பட்ட வரிசைகள், உறுதிப்படுத்தலுக்குப் பிறகு, நீங்கள் பொருளைச் சேமிக்கும்போது நீக்கப்படும்.',
'VG_Edit_3' => 'இன்னும் சரக்கு உள்ள வகை மாறுபாட்டை அகற்ற முடியாது. முதலில் அதன் சரக்கைச் சரிசெய்யவும் அல்லது பரிமாற்றவும்.',
'VG_Edit_4' => '"எளிய பட்டியல்" என்பதற்கு மாறினால் வரிசைகளும் அவற்றின் பெயர்களும் வைக்கப்படும், ஆனால் விருப்ப வரையறைகள் நீக்கப்படும்.',
'VG_Store_Title' => 'ஆன்லைன் கடையில்',
'VG_Store_Text' => 'வாடிக்கையாளர்கள் ஒவ்வொரு விருப்பத்திற்கும் ஒரு மதிப்பைத் தேர்வுசெய்வார்கள், எடுத்துக்காட்டாக நிறம் பின்னர் அளவு. இல்லாத சேர்க்கைகள் முடக்கப்படும், சரக்கில் இல்லாதவை அடித்துக் காட்டப்படும். தேர்வுசெய்யப்பட்ட வகை மாறுபாடே கார்ட்டுக்குச் செல்லும்.',
'Choose_Source' => 'மூலத்தைத் தேர்வுசெய்க',
'Portal_Request' => 'போர்டல் கோரிக்கை',
'Portal_Quotation_Requests' => 'போர்டல் விலைப்புள்ளி கோரிக்கைகள்',
'Warehouse_Invoice_Address_Help' => 'இந்தக் கிடங்கு வழங்கும் விலைப்பட்டியல்களில் அச்சிடப்படும் தெரு முகவரி. அமைப்புகளில் உள்ள நிறுவன முகவரியைப் பயன்படுத்தக் காலியாக விடவும்.',
'Warehouse_Logo_Help' => 'இந்தக் கிடங்கின் விலைப்பட்டியல்கள் மற்றும் POS ரசீதுகளில் அச்சிடப்படும் லோகோ. நிறுவன லோகோவைப் பயன்படுத்தக் காலியாக விடவும்.',
'Warehouse_Invoice_Footer_Help' => 'இந்தக் கிடங்கு வழங்கும் விலைப்பட்டியல்களின் கீழே அச்சிடப்படும் கூடுதல் குறிப்பு.',
'Issued_By' => 'வழங்கியவர்',
'Enable_Warehouse_Letterhead' => 'விலைப்பட்டியல்களில் கிடங்கு லெட்டர்ஹெட்',
'Enable_Warehouse_Letterhead_Hint' => 'விலைப்பட்டியல்கள், POS ரசீதுகள் மற்றும் பொது விலைப்பட்டியல் பக்கத்தில் வழங்கும் கிடங்கை அச்சிடவும்: அதன் பெயர் நிறுவனப் பெயருக்குப் பதிலாக வரும், அதன் முகவரி, தொலைபேசி, மின்னஞ்சல், லோகோ மற்றும் அடிக்குறிப்பு நிறுவனத்தினுடையவற்றுக்குப் பதிலாக வரும். கிடங்கில் காலியாக விடப்பட்ட எந்தப் புலமும் பொது நிறுவன அமைப்புகளைப் பயன்படுத்தும்.',
'Warehouse_Letterhead_Receipt_Notice' => 'கிடங்கு லெட்டர்ஹெட் இயக்கத்தில் உள்ளது: உண்மையான ரசீதில் அச்சிடப்படும் கடையின் பெயர், முகவரி மற்றும் தொலைபேசி விற்பனையை வழங்கிய கிடங்கிலிருந்து வரும், அதன் அடிக்குறிப்பு வாடிக்கையாளர் குறிப்பின் கீழே சேர்க்கப்படும்.',
'Warehouse_Letterhead_Receipt_Demo' => 'கிளை அடிக்குறிப்பு — கிடங்குகள் பகுதியில் ஒவ்வொரு கிடங்கிற்கும் அமைக்கவும்.',
