'Account_Ledger' => 'கணக்கு லெட்ஜர்',
'Closing_Balance' => 'முடிவு இருப்பு',
'Shopify_Link_Card_Hint' => 'உங்கள் கடையில் ஏற்கனவே உள்ள பட்டியலுடன் இந்தப் பொருளை இணைக்கவும், இதனால் ஒத்திசைவு இரண்டாவது ஒன்றை உருவாக்குவதற்குப் பதிலாக அதைப் புதுப்பிக்கும்.',
'Shopify_Not_Linked' => 'இணைக்கப்படவில்லை. பொருட்கள் push இந்தக் கடையில் புதிய பட்டியலை உருவாக்கும்.',
