'Shopify_Keep_Listing' => 'Shopify பட்டியலை வைத்திரு',
'Shopify_Keep_Listing_Hint' => 'கடையில் உள்ள தலைப்பு, விளக்கம், புகைப்படங்கள் மற்றும் விலைகள் அப்படியே இருக்கும். இந்தப் பொருளை இங்கே திருத்தும் வரை சரக்கு மட்டுமே அனுப்பப்படும்.',
'Shopify_Replace_Listing' => 'பட்டியலை இந்தப் பொருளால் மாற்று',
'Shopify_Replace_Listing_Hint' => 'அடுத்த பொருட்கள் push கடையின் தலைப்பு, விளக்கம், விலைகள் மற்றும் புகைப்படங்களை இங்கே உள்ளிடப்பட்டவற்றால் மேலெழுதும்.',
