'Opening_Batches' => 'தொடக்கத் தொகுதிகள்',
'Opening_Batches_Help' => 'ஏற்கனவே கையிருப்பில் உள்ள சரக்கிற்குத் தொகுதி எண் மற்றும் காலாவதியுடன் லேபிளிடவும். தொகுதிக் கண்காணிப்பு இயக்கப்படுவதற்கு முன் பெறப்பட்ட பொருட்களுக்கு இதைப் பயன்படுத்தவும். சரக்கு அளவுகள் மாற்றப்படாது.',
