'Set_Demo_Intro_Desc' => 'கடந்த 90 நாட்களில் பரவிய தயாரிப்புகள், வாடிக்கையாளர்கள், சப்ளையர்கள், விற்பனைகள், கொள்முதல்கள், மேற்கோள்கள் மற்றும் செலவுகள் — டாஷ்போர்டுகளையும் அறிக்கைகளையும் ஆராய ஏற்றது. உருவாக்கப்படும் அனைத்தும் குறிக்கப்பட்டு ஒரே கிளிக்கில் நீக்கக்கூடியவை.',
'Set_Generate_Demo_Data' => 'டெமோ தரவை உருவாக்கு',
'Set_Demo_Docs_Hint' => 'விற்பனைகள், கொள்முதல்கள் மற்றும் மேற்கோள்கள் டெமோ தயாரிப்புகள், வாடிக்கையாளர்கள் மற்றும் சப்ளையர்களை மட்டுமே பயன்படுத்தும் — அவை இல்லாமல் ஆவணங்களைக் கோரினால் ஒரு சிறிய தொகுப்பு தானாக உருவாக்கப்படும்.',
