'Set_Env_Written_Directly_Desc' => 'இங்கே பட்டியலிடப்பட்ட விசைகளை மட்டுமே திருத்த முடியும். ஒவ்வொரு சேமிப்புக்கும் முன் முந்தைய .env இன் காப்புப்பிரதி {path} இல் வைக்கப்படும். விசையை நீக்கி உள்ளமைந்த இயல்புநிலையைப் பயன்படுத்த ஒரு புலத்தைக் காலியாக விடவும்.',
