'Set_ModT_Accounting_Desc' => 'கணக்கு அட்டவணை, ஜர்னல் பதிவுகள், நிதி அறிக்கைகள், செலவுகள் மற்றும் வைப்புகள்.',
'Set_ModT_EWallet_Desc' => 'வாடிக்கையாளர் வாலட் இருப்புகள் மற்றும் வாலட் உருப்படிகள்.',
'Set_ModT_Commissions_Desc' => 'முகவர் கமிஷன் திட்டங்கள், விதிகள் மற்றும் ரசீதுகள்.',
'Set_ModT_Promotions_Desc' => 'POS செக்அவுட்டில் பயன்படுத்தப்படும் தள்ளுபடி ஊக்குவிப்புகள்.',
'Set_ModT_Kitchen_Desc' => 'சமையலறைக் காட்சித் திரை மற்றும் சமையலறைச் செயல்திறன் அறிக்கை.',
'Set_ModT_Ecommerce_Platforms_Desc' => 'அனைத்து வெளிப்புற ஸ்டோர் இணைப்பிகள்: WooCommerce, Shopify, Salla, PrestaShop மற்றும் Jumia.',
'Set_ModT_Woo_Desc' => 'WooCommerce ஸ்டோர் ஒத்திசைவு.',
'Set_ModT_Shopify_Desc' => 'Shopify ஸ்டோர் ஒத்திசைவு மற்றும் பதிவுகள்.',
'Set_ModT_Salla_Desc' => 'Salla ஸ்டோர் ஒத்திசைவு: தயாரிப்புகள், இருப்பு மற்றும் ஆர்டர்கள்.',
'Set_ModT_PrestaShop_Desc' => 'PrestaShop ஸ்டோர் ஒத்திசைவு.',
'Set_ModT_Jumia_Desc' => 'Jumia சந்தை: விலை & இருப்பு அனுப்புதல், ஆர்டர் இறக்குமதி.',
'Set_ModT_Documents_Desc' => 'மைய ஆவணச் சேமிப்பு மற்றும் காப்பகப்படுத்தல்.',
'Set_ModT_Subscription_Products' => 'சந்தாத் தயாரிப்புகள்',
'Set_ModT_Subscription_Desc' => 'தொடர் தயாரிப்புச் சந்தாக்கள்.',
'Set_ModT_Manufacturing_Desc' => 'பொருட்களின் பட்டியல்கள், உற்பத்தி ஆர்டர்கள், பணி மையங்கள், தரம் மற்றும் திட்டமிடல்.',
'Set_ModT_Assets_Desc' => 'நிறுவனச் சொத்துகள், ஒதுக்கீடுகள், பராமரிப்பு, இடமாற்றங்கள் மற்றும் தேய்மானம்.',
'Set_ModT_Projects' => 'திட்டங்கள் & பணிகள்',
'Set_ModT_Projects_Desc' => 'திட்டங்கள், பணிகள், மைல்கற்கள், நேரத்தாள்கள் மற்றும் திட்ட அறிக்கைகள்.',
'Set_ModT_Bookings_Desc' => 'முன்பதிவுகள், நாட்காட்டி மற்றும் தட்டுகள்.',
'Set_ModT_Service_Desc' => 'சேவைப் பணிகள், தொழில்நுட்பர்கள் மற்றும் சரிபார்ப்புப் பட்டியல்கள்.',
'Set_ModT_Fleet_Desc' => 'வாகனங்கள், பராமரிப்பு, எரிபொருள் பதிவுகள், ஒதுக்கீடுகள் மற்றும் வாகனக் குழு அறிக்கைகள்.',
'Set_ModT_Crm_Desc' => 'லீட்கள், விற்பனை பைப்லைன் மற்றும் டீல்கள், செயல்பாடுகள் மற்றும் பின்தொடர்தல்கள், லீட் சேகரிப்பு மற்றும் விற்பனை அறிக்கைகள்.',
'Set_ModT_Rental_Desc' => 'வாடகை ஒப்பந்தங்கள், முன்பதிவுகள், விலைப்பட்டியல்கள் & கட்டணங்கள், பராமரிப்பு & செலவுகள், கிடைக்கும் நிலை காலவரிசை, பொருட்கள் மற்றும் வாடிக்கையாளர்கள்.',
'Set_ModT_Hospital_Desc' => 'நோயாளிகள், மருத்துவர்கள், சந்திப்புகள், வருகைகள், அனுமதிகள், வார்டுகள், ஆய்வகம் மற்றும் பில்லிங்.',
'Set_ModT_School_Desc' => 'மாணவர்கள், ஆசிரியர்கள், கல்வி, தேர்வுகள், கால அட்டவணை மற்றும் கட்டணங்கள்.',
'Set_Sidebar_Intro_Title' => 'பக்கப்பட்டியை மறுசீரமைக்க இழுத்து விடவும்',
'Set_Sidebar_Intro_Desc' => 'தொகுதிகளை மறுவரிசைப்படுத்தவும், ஒரு தொகுதிக்குள் உருப்படிகளை மறுவரிசைப்படுத்தவும், அல்லது ஒரு உருப்படியை வேறு தொகுதிக்குள் இழுக்கவும். தொகுதிகள் எப்போதும் மேல் நிலையிலேயே இருக்கும், உருப்படிகள் தொகுதிகளாக மாற முடியாது. சேமிக்கப்பட்ட அமைப்பு ஒவ்வொரு பயனருக்கும் பொருந்தும்.',
