'Set_Sidebar_Groups_Under_Module' => 'குழுக்களை ஒரு தொகுதியின் கீழ் நேரடியாக மட்டுமே வைக்க முடியும்.',
'Set_Sidebar_Items_Inside' => 'உருப்படிகள் ஒரு தொகுதி அல்லது குழுவுக்குள்ளேயே இருக்க வேண்டும்.',
