'Upd_Note_Code_Changes_Lost' => 'குறிப்பு 1: நீங்கள் குறியீட்டில் கைமுறையாக ஏதேனும் மாற்றங்கள் செய்திருந்தால், உங்கள் மாற்றங்கள் இழக்கப்படும்.',
'Upd_Manual_Steps_Intro' => 'உங்கள் பயன்பாட்டைப் புதுப்பிக்க இந்தப் படிகளைப் பின்பற்றவும்',
'Upd_Note_Permission_Only' => 'குறிப்பு 2: நிர்வாகி அல்லது "{perm}" அனுமதி உள்ள பயனர் மட்டுமே கணினியை மேம்படுத்த முடியும்',
'Upd_Manual_Step_Backup_Db' => 'உங்கள் தரவுத்தளத்தின் காப்புப்பிரதியை எடுக்கவும். {backup} க்குச் சென்று, Generate Backup ஐக் கிளிக் செய்யவும் — அதை {path} இல் காணலாம் — அல்லது PhpMyAdmin இலிருந்து உங்கள் தரவுத்தளத்தை ஏற்றுமதி செய்து உங்கள் கணினியில் சேமிக்கவும்.',
'Upd_Manual_Step_Backup_Files' => 'புதுப்பிப்பதற்கு முன் உங்கள் கோப்புகளின் காப்புப்பிரதியை எடுக்கவும்.',
'Upd_Manual_Step_Download' => 'உங்கள் CodeCanyon கணக்கிலிருந்து சமீபத்திய பதிப்பைப் பதிவிறக்கிப் பிரித்தெடுக்கவும்.',
'Upd_Manual_Step_Remove' => 'பின்வருவனவற்றைத் {except}, முந்தைய கோப்புகளை நீக்கவும்:',
'Upd_Except' => 'தவிர',
'Upd_File_Label' => 'கோப்பு: {name}',
'Upd_Folder_Label' => 'கோப்புறை: {name}',
'Upd_Manual_Step_Reupload' => 'மேலே உள்ள அதே மூன்று பாதைகளைத் {except}, புதிய புதுப்பிப்பிலிருந்து கோப்புகளையும் கோப்புறைகளையும் மீண்டும் பதிவேற்றவும்.',
'Upd_Manual_Step_Visit' => 'உங்கள் தரவுத்தளத்தைப் புதுப்பிக்க {url} ஐப் பார்வையிடவும்.',
'Upd_Manual_Step_Clear_Cache' => 'உங்கள் உலாவியின் தற்காலிகச் சேமிப்பை முழுமையாக அழிக்கவும்.',
'Upd_Manual_Step_Done' => 'முடிந்தது! புதுப்பிக்கப்பட்ட பயன்பாட்டை அனுபவியுங்கள்.',
'Upd_Note_Blank_Pages' => 'குறிப்பு: ஏதேனும் பக்கங்கள் ஏற்றப்படாவிட்டால் அல்லது வெறுமையாக இருந்தால், உங்கள் உலாவியின் தற்காலிகச் சேமிப்பை அழித்துள்ளீர்களா என்பதை உறுதிசெய்யவும்.',
'Upd_Guide_Before_Title' => '1. புதுப்பிப்பதற்கு முன்',
'Upd_Guide_Before_Download' => 'உங்கள் CodeCanyon கணக்கிலிருந்து ({path}) பயன்பாட்டின் {package} பதிவிறக்கவும். அதைப் பிரித்தெடுக்க வேண்டாம் — புதுப்பிப்பான் பதிவிறக்கியபடியே உள்ள ZIP-ஐ எதிர்பார்க்கிறது.',
'Upd_Latest_Full_Zip' => 'சமீபத்திய முழு ZIP தொகுப்பை',
'Upd_Guide_Before_Admin' => '{perm} அனுமதி உள்ள நிர்வாகியாக உள்நுழைந்துள்ளீர்கள் என்பதை உறுதிசெய்யவும். வேறு யாரும் புதுப்பிப்பானைப் பார்க்கவோ இயக்கவோ முடியாது.',
'Upd_Guide_Before_Quiet' => 'அமைதியான நேரத்தைத் தேர்வு செய்யவும்: புதுப்பிப்பின்போது பயன்பாடு சிறிது நேரம் பராமரிப்புப் பயன்முறைக்கு மாறும், மற்ற பயனர்கள் வெளியே பூட்டப்படுவார்கள்.',
'Upd_Guide_Before_No_Manual' => 'கைமுறையாகக் காப்புப்பிரதி எடுக்கவோ, கோப்புகளைப் பிரித்தெடுக்கவோ, கட்டளைகளை இயக்கவோ, உள்ளமைவுக் கோப்புகளைத் திருத்தவோ, தரவுத்தளத்தைத் தொடவோ உங்களுக்கு அவசியம் {not} — புதுப்பிப்பான் அனைத்தையும் தானாகச் செய்கிறது. (கூடுதல் கைமுறைக் காப்புப்பிரதி எடுப்பதில் தீங்கு இல்லை, நிச்சயமாக.)',
'Upd_Not' => 'இல்லை',
'Upd_Guide_Code_Overwritten' => 'நீங்கள் பயன்பாட்டுக் குறியீட்டைக் கைமுறையாக மாற்றியிருந்தால், உங்கள் மாற்றங்கள் புதுப்பிப்பால் மேலெழுதப்படும். உங்கள் தரவு, பதிவேற்றங்கள், அமைப்புகள் மற்றும் .env எப்போதும் பாதுகாக்கப்படும்.',
'Upd_Guide_Running_Title' => '2. புதுப்பிப்பை இயக்குதல்',
'Upd_Guide_Run_Open' => '{path} (இந்தப் பக்கம்) ஐத் திறந்து {tab} தாவலிலேயே இருக்கவும்.',
'Upd_Guide_Run_Upload' => '{upload}: பதிவிறக்கிய தொகுப்பைப் பதிவேற்றப் பெட்டிக்குள் கிளிக் செய்யவும் அல்லது இழுக்கவும். பெரிய கோப்புகள் சிறு பகுதிகளாகப் பதிவேற்றப்படுகின்றன, எனவே குறைந்த பதிவேற்ற வரம்புகளுள்ள பகிர்ந்த ஹோஸ்டிங்கிலும் இது வேலை செய்யும். ஒரு checksum சிதைந்த அல்லது முழுமையற்ற பதிவேற்றங்களுக்கு எதிராகப் பாதுகாக்கிறது.',
'Upd_Upload_The_Zip' => 'ZIP-ஐப் பதிவேற்றவும்',
'Upd_Guide_Run_Validation' => 'பதிவேற்றத்திற்குப் பிறகு {auto} ({button} பொத்தானைக் கொண்டு மீண்டும் இயக்கலாம்). கணினி சரிபார்ப்பவை: ZIP ஒருமைப்பாடு, தொகுப்பு அமைப்பு மற்றும் முழுமை, பதிப்பு இணக்கத்தன்மை (பதிப்பைக் குறைத்தல் மறுக்கப்படும்), தேவையான PHP பதிப்பு மற்றும் நீட்டிப்புகள், கோப்பு அனுமதிகள், இலவச வட்டு இடம், தரவுத்தள இணைப்பு, உள்ளமைவு, மற்றும் வேறு எந்தப் புதுப்பிப்பும் இயங்கவில்லை என்பது.',
'Upd_Validation_Runs_Automatically' => 'சரிபார்ப்பு தானாக இயங்கும்',
'Upd_Guide_Run_Review' => '{panel} பலகத்தை மதிப்பாய்வு செய்யவும். ஒவ்வொரு முக்கியமான சரிபார்ப்பும் தேர்ச்சி பெறும்போது மட்டுமே {button} பொத்தான் தோன்றும். ஒரு சரிபார்ப்பு தோல்வியடைந்தால், எதைச் சரிசெய்ய வேண்டும் என்பதைச் செய்தி துல்லியமாகக் கூறும்.',
'Upd_Guide_Run_Click' => '{button} ஐக் கிளிக் செய்து உறுதிப்படுத்தவும். பின்னர் {keep}, முன்னேற்றப் பட்டையைக் கவனியுங்கள். கணினி வரிசையாகச் செய்பவை:',
'Upd_Keep_Page_Open' => 'இந்தப் பக்கத்தைத் திறந்தே வைத்திருங்கள்',
'Upd_Guide_Phase_Backup' => '{label} — முழுத் தரவுத்தள dump, புதுப்பிப்பு மாற்றக்கூடிய ஒவ்வொரு பயன்பாட்டுக் கோப்பின் ZIP, மற்றும் {env} இன் நகல் ஆகியவை உருவாக்கப்பட்டு {verified}. உங்கள் பதிவேற்றங்கள் ({images}) மற்றும் {storage} ஆகியவை புதுப்பிப்பால் ஒருபோதும் தொடப்படுவதில்லை, எனவே அவை காப்பகப்படுத்தப்படுவதில்லை. காப்புப்பிரதியை உருவாக்க முடியாவிட்டால், புதுப்பிப்பு இங்கேயே நின்றுவிடும், எதுவும் மாற்றப்படாது.',
'Upd_Verified' => 'சரிபார்க்கப்படுகின்றன',
'Upd_Guide_Phase_Prepare' => '{label} — புதிய பதிப்பு ஒரு staging பகுதியில் பிரித்தெடுக்கப்பட்டு மீண்டும் சரிபார்க்கப்படுகிறது. நேரலைப் பயன்பாடு இன்னும் தொடப்படவில்லை.',
'Upd_Guide_Phase_Maintenance' => '{label} — பராமரிப்புப் பயன்முறை இயக்கப்படுகிறது; பார்வையாளர்கள் "விரைவில் திரும்புவோம்" என்ற நட்பான திரையைக் காண்பார்கள்.',
'Upd_Guide_Phase_Files' => '{label} — புதிய கோப்புகள் கிட்டத்தட்ட உடனடியாக மாற்றப்படுகின்றன; பழைய கோப்புகள் rollback-க்காகத் தனியாக வைக்கப்படுகின்றன. பாதுகாக்கப்பட்ட பாதைகள் ({env}, {storage}, {images}) ஒருபோதும் மாற்றப்படுவதில்லை.',
'Upd_Guide_Phase_Database' => '{label} — migrations இயங்குகின்றன, பின்னர் அனுமதிகள், மொழிபெயர்ப்புகள் மற்றும் வார்ப்புருக்கள் புதுப்பிக்கப்படுகின்றன.',
'Upd_Guide_Phase_Cache' => '{label} — அனைத்துத் தற்காலிகச் சேமிப்புகளும் அழிக்கப்பட்டு மீண்டும் உருவாக்கப்படுகின்றன.',
'Upd_Guide_Phase_Verify' => '{label} — புதிய பதிப்பு தொடங்குகிறது, தரவுத்தளம் வேலை செய்கிறது, அனைத்து migrations-ும் இயங்கின, உள்ளமைவு செல்லுபடியானது என்பதை நலச் சரிபார்ப்புகள் உறுதிப்படுத்துகின்றன.',
'Upd_Guide_Phase_Done' => '{label} — பராமரிப்புப் பயன்முறை நீக்கப்பட்டு தற்காலிகக் கோப்புகள் சுத்தம் செய்யப்படுகின்றன.',
'Upd_Guide_Run_Success' => '{success} எனக் காணும்போது, {reload} ஐக் கிளிக் செய்து, புதிய நிர்வாகப் பலக assets ஏற்றப்படும்படி உங்கள் உலாவியை முழுமையாகப் புதுப்பிக்கவும் ({keys}).',
'Upd_Update_Successful_Short' => 'புதுப்பிப்பு வெற்றிகரமாக முடிந்தது',
'Upd_Guide_No_Internet' => 'புதுப்பிப்பின்போது இணைய இணைப்பு தேவையில்லை — அனைத்தும் பதிவேற்றிய ZIP-இலிருந்தே வருகின்றன. உங்கள் இணைப்பை இழப்பதோ உலாவியை மூடுவதோ புதுப்பிப்பைச் சேதப்படுத்தாது: அது எங்கே நின்றது என்பதைச் சர்வர் துல்லியமாக நினைவில் வைத்திருக்கும்.',
'Upd_Guide_Wrong_Title' => '3. ஏதேனும் தவறு நடந்தால்',
'Upd_Guide_Wrong_Rollback' => '{label} — கோப்புகள் மாறத் தொடங்கிய பிறகு ஏதேனும் தோல்வியடைந்தால் (பிரித்தெடுத்தல் பிழை, migration தோல்வி, நலச் சரிபார்ப்புத் தோல்வி, வட்டு நிரம்பியது, …), கணினி சரிபார்க்கப்பட்ட காப்புப்பிரதியிலிருந்து முந்தைய கோப்புகளையும் தரவுத்தளத்தையும் தானாக மீட்டெடுத்து, பராமரிப்புப் பயன்முறையை நீக்கி, {message} எனப் புகாரளிக்கும். நீங்கள் தொடங்கிய இடத்திலேயே சரியாக இருப்பீர்கள்.',
'Upd_Automatic_Rollback' => 'தானியங்கி rollback',
'Upd_Failed_Previous_Restored' => 'புதுப்பிப்பு தோல்வியடைந்தது — முந்தைய பதிப்பு மீட்டெடுக்கப்பட்டது',
'Upd_Guide_Wrong_Interrupted' => '{label} (சர்வர் மறுதொடக்கம், நேர முடிவு, மூடப்பட்ட உலாவி, மின் தடை) — இந்தப் பக்கத்தை மீண்டும் திறக்கும்போது, ஒரு சிவப்புப் பேனர் இரண்டு பாதுகாப்பான தேர்வுகளை வழங்கும்: {resume} (அது நின்ற சரியான படியிலிருந்து தொடரும்) அல்லது {rollback} (காப்புப்பிரதியிலிருந்து முந்தைய பதிப்பை மீட்டெடுக்கும்).',
'Upd_Interrupted_Update' => 'இடைநிறுத்தப்பட்ட புதுப்பிப்பு',
'Upd_Guide_Wrong_Unreachable' => '{label} — {path} இல் உள்ள தனித்த {console} ஐப் பயன்படுத்தவும். தளம் பராமரிப்புப் பயன்முறையில் இருக்கும்போதும் நிர்வாகப் பலக assets சேதமடைந்திருக்கும்போதும் இது வேலை செய்யும், அதே Continue / Roll back செயல்களை வழங்கும். பராமரிப்புத் திரையின் கீழே ஒரு மறைவான "Administrator access" இணைப்பும் உள்ளது.',
'Upd_Admin_Unreachable' => 'நிர்வாகப் பலகத்தை அணுக முடியவில்லை',
'Upd_Recovery_Console' => 'மீட்புக் கன்சோல்',
'Upd_Guide_Wrong_Locked_Out' => '{label} — ஒரு புதுப்பிப்பு இயங்கும்போது, இந்தப் பக்கம் ஒரு {link} ஐக் காட்டும். மீண்டும் உள்ளே வர வேண்டுமானால் (எடுத்துக்காட்டாக உங்கள் அமர்வு காலாவதியான பிறகு) அதைச் சேமிக்கவும்; இது பராமரிப்புத் திரையைக் கடந்து மீண்டும் உள்நுழைய உதவும்.',
'Upd_Locked_Out_Maintenance' => 'பராமரிப்புப் பயன்முறையால் வெளியே பூட்டப்பட்டது',
'Upd_Bypass_Link' => 'தவிர்ப்பு இணைப்பு',
'Upd_Guide_Wrong_Concurrent' => '{label} — அவர்கள் {message} ஐக் காண்பார்கள். ஒரே நேரத்தில் ஒரு புதுப்பிப்பு மட்டுமே இயங்க முடியும்.',
'Upd_Another_Admin_Updating' => 'மற்றொரு நிர்வாகி அதே நேரத்தில் புதுப்பிக்க முயல்கிறார்',
'Upd_Guide_Backups_Title' => '4. காப்புப்பிரதிகள் & மீட்டெடுப்பு',
'Upd_Guide_Backups_Created' => 'ஒவ்வொரு புதுப்பிப்பும் எதையும் தொடுவதற்கு {before} ஒரு காப்புப்பிரதியை உருவாக்குகிறது: புதுப்பிப்பு மாற்றக்கூடிய அனைத்துப் பயன்பாட்டுக் கோப்புகள், {env} இன் நகல், மற்றும் முழுத் தரவுத்தள dump. பதிவேற்றங்களும் {storage} உம் புதுப்பிப்பால் ஒருபோதும் மாற்றப்படுவதில்லை, எனவே அவை இதில் சேர்க்கப்படுவதில்லை — அவற்றுக்கு உங்கள் சொந்தக் காப்புப்பிரதிகளை வைத்திருங்கள். காப்புப்பிரதிகள் {path} இல் இருக்கும், வலையிலிருந்து ஒருபோதும் அணுக முடியாது.',
'Upd_Before' => 'முன்பே',
'Upd_Guide_Backups_Panel' => '{tab} தாவலில் உள்ள {panel} பலகம் அவற்றைத் தேதி, பதிப்பு மற்றும் அளவுடன் பட்டியலிடுகிறது. அங்கிருந்து எந்த முழுமையான காப்புப்பிரதியையும் {restore} (கோப்புகள் + தரவுத்தளம் — தற்போதைய தரவுத்தளத்தின் பாதுகாப்பு நகல் முதலில் எடுக்கப்படும்) அல்லது பழையவற்றை {delete}.',
'Upd_Restore_Verb' => 'மீட்டெடுக்கலாம்',
'Upd_Delete_Verb' => 'நீக்கலாம்',
'Upd_Guide_Backups_Retention' => 'எத்தனை காப்புப்பிரதிகள் வைக்கப்பட வேண்டும் என்பதைத் தேர்வு செய்ய {keep} ஐப் பயன்படுத்தவும்; ஒவ்வொரு வெற்றிகரமான புதுப்பிப்புக்குப் பிறகும் பழையவை தானாக நீக்கப்படும். எஞ்சியிருக்கும் ஒரே முழுமையான காப்புப்பிரதியை ஒருபோதும் நீக்க முடியாது — நீங்கள் எப்போதும் திரும்புவதற்கு ஒரு வழியை வைத்திருப்பீர்கள்.',
'Upd_Guide_Manual_Title' => '5. கைமுறைப் புதுப்பிப்பு (மாற்று முறை)',
'Upd_Guide_Manual_Text' => 'நீங்கள் கைமுறையாகப் புதுப்பிக்க விரும்பினால், அல்லது உங்கள் சர்வரில் பதிவேற்றியைப் பயன்படுத்த முடியாவிட்டால், இந்தப் பக்கத்தின் {tab} தாவலில் உள்ள படிப்படியான வழிமுறைகளைப் பின்பற்றவும்.',
'Upd_Guide_Clear_Cache_First' => 'எந்தப் புதுப்பிப்புக்குப் பிறகும் பக்கங்கள் சேதமடைந்தோ வெறுமையாகவோ தோன்றினால், முதலில் உங்கள் உலாவியின் தற்காலிகச் சேமிப்பை அழிக்கவும் — கிட்டத்தட்ட எப்போதும் அதுவே காரணம்.',
'Upd_Restore_Backup_Confirm' => 'இந்தக் காப்புப்பிரதியை மீட்டெடுக்கவா? தற்போதைய கோப்புகளும் தற்போதைய தரவுத்தளமும் காப்புப்பிரதியால் மாற்றப்படும். தற்போதைய தரவுத்தளத்தின் பாதுகாப்பு நகல் முதலில் எடுக்கப்படும். (v{version} — {date})',
'Woo_Guide_Lead' => 'ஒரு WooCommerce கடை ERP உடன் எவ்வாறு ஒத்திசைவாக இருக்கிறது. கீழே உள்ள cron வரிகள் இந்தச் சர்வருக்காக உருவாக்கப்பட்டவை, எனவே அவற்றை நேரடியாக நகலெடுக்கலாம்.',
'Woo_Guide_Ways_Note' => 'Shopify போலன்றி, WooCommerce தானாக ERP-க்கு எதையும் அனுப்புவதில்லை — இங்கே webhook பெறுநர் இல்லை, எனவே {in} வரும் அனைத்தும் அட்டவணைப்படியே வருகின்றன. {out} செல்லும் இருப்பு மட்டுமே உடனடியாக இருக்க முடியும்.',
'Woo_In' => 'உள்ளே',
'Woo_Out' => 'வெளியே',
'Woo_Guide_Both_Ways_Title' => 'இரு வழிகளுக்கும் முதலில் இது தேவை',
'Woo_Api_Keys' => 'API விசைகள்',
'Woo_Guide_Api_Keys_Text' => '{path}, அனுமதி {perm}. consumer key மற்றும் secret-ஐ ஸ்டோர் URL உடன் {settings} தாவலில் நகலெடுக்கவும் — உங்கள் தளத்தின் முகவரி, இறுதியில் சாய்வுக்கோடு இல்லாமல், எ.கா. {example}.',
'Woo_Credentials_Saved' => 'நற்சான்றுகள் சேமிக்கப்பட்டன',
'Woo_Not_Configured_Yet' => 'இன்னும் உள்ளமைக்கப்படவில்லை',
'Woo_Guide_Wp_App_Password_Title' => 'WordPress application password (விருப்பத்தேர்வு)',
'Woo_Guide_Wp_App_Password_Text' => 'தயாரிப்புப் படங்களுக்கு மட்டுமே பயன்படுத்தப்படுகிறது. WooCommerce API தயாரிப்புகள், இருப்பு, வகைகள், பிராண்டுகள், வாடிக்கையாளர்கள் மற்றும் ஆர்டர்களை நகர்த்துகிறது; WordPress API மீடியா நூலகத்தில் தேடி, இன்னும் இல்லாத படத்தைப் பதிவேற்றுகிறது.',
'Woo_Guide_Wp_App_Password_Note' => 'மீடியாவை நிர்வகிக்கக்கூடிய WordPress பயனரைப் பயன்படுத்தி, {path} இன் கீழ் கடவுச்சொல்லை உருவாக்கவும். இரண்டு புலங்களையும் காலியாக விட்டாலும் அனைத்தும் ஒத்திசைக்கப்படும் — பட இணைப்பு மட்டுமே தவிர்க்கப்படும்.',
'Woo_Guide_Pick_Way_Title' => 'பின்னர் அது எவ்வாறு ஒத்திசைவாக இருக்கும் என்பதைத் தேர்வு செய்யவும்',
'Woo_Right_Away' => 'உடனடியாக',
'Woo_Stock_Live' => 'இருப்பு நேரலையில்',
'Woo_Stock_Not_Live' => 'இருப்பு நேரலையில் இல்லை',
'Woo_Guide_Realtime_Lead' => 'ஒரே திசை மட்டும்: ERP-இலிருந்து வெளியேறும் இருப்பும் தயாரிப்புகளும். WooCommerce-இல் செய்யப்படும் ஆர்டர்களும் தயாரிப்புத் திருத்தங்களும் இன்னும் அட்டவணைப்படியே வருகின்றன — மற்ற தாவலைப் பார்க்கவும்.',
'Woo_Push_Stock_On_Change' => 'இருப்பு மாறிய உடனே அனுப்பு',
'Woo_Setting_People_Miss' => 'மக்கள் தவறவிடும் அமைப்பு இதுதான்',
'Woo_Guide_Pos_Sale_Not_Reach' => 'ஒரு POS விற்பனை தானாக WooCommerce-ஐ {not}. அணைத்து வைத்தால், அடுத்த இருப்பு ஒத்திசைவில் மட்டுமே கடைக்குத் தெரியவரும் — இயல்பாக ஒரு மணிநேரம் — அந்த இடைவெளியில் நீங்கள் ஏற்கனவே கவுண்டரில் விற்ற ஒரு அலகை அது விற்கக்கூடும்.',
'Woo_Does_Not' => 'சென்றடையாது',
'Woo_Guide_Tick_Instant' => '{settings} தாவலில் {option} ஐத் தேர்வு செய்யவும். அமைப்பு அவ்வளவுதான் — worker இல்லை, cron இல்லை. ஒவ்வொரு விற்பனை, திருப்பல், சரிசெய்தல், இடமாற்றம் மற்றும் பெறப்பட்ட கொள்முதலும் விற்பனை சேமிக்கப்பட்ட உடனே அந்தத் தயாரிப்புகளை மட்டும் அனுப்பும், இருபது வரி விற்பனைக்கு ஒரே ஒரு push, இருபது அல்ல. கவுண்டர் ஒருபோதும் அதற்காகக் காத்திருக்காது.',
'Woo_Currently' => 'தற்போது:',
'Woo_Instant_On_Text' => 'இயக்கத்தில் — மாற்றத்தின்போது இருப்பு அனுப்பப்படும்',
'Woo_Instant_Off_Text' => 'அணைப்பில் — அட்டவணைப்படி மட்டுமே இருப்பு',
'Woo_Guide_Instant_Note' => 'ஏற்கனவே WooCommerce உடன் இணைக்கப்பட்ட தயாரிப்புகள் மட்டுமே அனுப்பப்படும் — ஒருபோதும் ஒத்திசைக்கப்படாத ஒன்றுக்குக் கடையில் திருத்துவதற்கு எதுவும் இல்லை. மாறுபாடுள்ள தயாரிப்புகள் அவற்றின் தாய் வழியாகச் செல்லும், ஒரு combo அதன் கூறுகள் ஏதேனும் நகரும்போது மீண்டும் அனுப்பப்படும். மொத்தச் செயல்பாடுகள் (ஒரு தயாரிப்பை நீக்குதல், ஒரு கிடங்கை மீட்டமைத்தல்) நிகழ்வைத் தூண்டாமல் இருப்பை எழுதுகின்றன, மணிநேர இருப்பு ஒத்திசைவையும் வைத்திருக்க இது ஒரு காரணம்.',
'Woo_Push_Products_On_Save' => 'தயாரிப்புகள் சேமிக்கப்பட்ட உடனே அனுப்பு',
'Woo_Guide_Tick_Auto_Products' => '{settings} தாவலில் {option} ஐத் தேர்வு செய்தால், Stocky-இல் உருவாக்கப்பட்ட, திருத்தப்பட்ட அல்லது நகலெடுக்கப்பட்ட தயாரிப்பு சேமிக்கப்பட்ட உடனே WooCommerce-க்கு அனுப்பப்படும் — விவரங்கள், விலை, மாறுபாடுகள் மற்றும் படங்கள், பின்னர் அதன் இருப்பு. இரவு நேரத் தயாரிப்பு ஒத்திசைவுக்காகக் காத்திருக்காமல் புதிய தயாரிப்பு உடனடியாகக் கடையில் உருவாக்கப்படும்.',
'Woo_On' => 'இயக்கம்',
'Woo_Off' => 'அணைப்பு',
'Woo_Guide_Bulk_Imports_Note' => 'மொத்த இறக்குமதிகள் ஒவ்வொன்றாக அனுப்பப்படுவதில்லை — இறக்குமதிக்குப் பிறகு தயாரிப்பு ஒத்திசைவை இயக்கவும். அனுப்பப்படும் தயாரிப்பு சரியான வகையில் சேர, முதலில் வகைகளையும் பிராண்டுகளையும் ஒத்திசைக்கவும்.',
'Woo_Nothing_Else_To_Install' => 'வேறு எதையும் நிறுவ வேண்டியதில்லை',
'Woo_Guide_Same_Process' => 'queue worker இல்லை, cron பதிவு இல்லை. விற்பனைக்குச் சேவை செய்த அதே செயல்முறையில், பதில் திரும்பிச் சென்ற {after} push இயங்குகிறது, எனவே கவுண்டர் ஒருபோதும் WooCommerce-க்காகக் காத்திருக்காது. Push-கள் ஒன்றுடன் ஒன்று மோதுவதில்லை: ஒன்று இயங்கும்போது செய்யப்படும் மாற்றங்கள் அதற்காகக் காத்திருந்து உடனே பின்னர் அனுப்பப்படும்.',
'Woo_After' => 'பிறகு',
'Woo_Guide_Shop_Stops_Answering' => 'பதிலளிப்பதை நிறுத்தும் கடை எட்டு வினாடிகளுக்குப் பிறகு கைவிடப்படும், ஒவ்வொரு விற்பனையும் மீண்டும் அதற்காகக் காத்திருக்காமல் இருக்க push-கள் ஐந்து நிமிடங்கள் இடைநிறுத்தப்படும்; இடையில் வந்த மாற்றங்கள் இடைநிறுத்தத்திற்குப் பிறகான முதல் push உடன் அனுப்பப்படும், மணிநேர இருப்பு ஒத்திசைவு எப்படியும் சரிசெய்யும். ஒவ்வொரு இடைநிறுத்தமும் Logs தாவலில் பதிவுசெய்யப்படும்.',
'Woo_Guide_Artisan_Exception' => 'ஒரு விதிவிலக்கு: artisan கட்டளையால் செய்யப்படும் இருப்பு மாற்றத்திற்குப் பின்தொடர பதில் இல்லை, எனவே அது {queue} இல் வரிசைப்படுத்தப்படுகிறது. அவையும் உடனடியாக அனுப்பப்பட, அந்த queue-ஐ இயக்கவும்:',
'Woo_Cron_Line_Copied' => 'Cron வரி நகலெடுக்கப்பட்டது',
'Woo_Command_Copied' => 'கட்டளை நகலெடுக்கப்பட்டது',
'Woo_Guide_Not_Woo_Queue' => 'வேண்டுமென்றே {queue} queue அல்ல: அது மணிநேரக் கணக்கில் நீளும் பட்டியல் batches-ஐ எடுத்துச் செல்கிறது, அதன் பின்னால் வரிசைப்படுத்தப்படும் உடனடி push உடனடியாக இருக்காது.',
'Woo_On_A_Schedule' => 'அட்டவணைப்படி',
'Woo_Guide_Scheduled_Lead' => 'அனைத்தும் அவ்வப்போது இரு திசைகளிலும் மீண்டும் சரிபார்க்கப்படுகின்றன. இப்படித்தான் ஆர்டர்கள் ERP-ஐ அடைகின்றன, பட்டியல் வெளியிடப்படுகிறது, வேகமான வழி தவறவிட்ட எதுவும் சரிசெய்யப்படுகிறது. ஒவ்வொரு job-க்கும் தனி cron பதிவு உள்ளது, எனவே நீங்கள் விரும்புவதை மட்டும் இயக்கலாம்.',
'Woo_Guide_Sync_Drains_Queue' => '{command} இயங்கும்போது தனது சொந்த queue-ஐ இயக்குகிறது, எனவே இந்த வரிகளுக்குத் தனி worker தேவையில்லை. Windows-இல், {program} நிரலுடனும் அதே arguments உடனும் {path} இல் தொடங்கும் Task Scheduler-ஐப் பயன்படுத்தவும்.',
'Woo_Or_No_Cron' => 'அல்லது cron இல்லாமலேயே',
'Woo_Guide_No_Cron_Text' => 'இங்குள்ள ஒவ்வொரு தாவலும் தேவைக்கேற்ப ஒத்திசைக்கிறது, கைமுறை ஒத்திசைவு பக்கம் திறந்திருக்கும்போது தனது சொந்த batches-ஐ இயக்குகிறது — எனவே ஒரு சிறிய கடை எந்த cron பதிவும் இல்லாமல் இயங்க முடியும். நீங்கள் இழப்பது யாரும் கவனிக்காதபோது நடக்கும் அனைத்தும்: யாராவது பொத்தானை அழுத்தும்போது மட்டுமே ஆர்டர்கள் வரும்.',
'Woo_Commands_Worth_Knowing' => 'அறிய வேண்டிய கட்டளைகள்',
'Woo_Worth_Knowing' => 'அறிய வேண்டியவை',
'Woo_Guide_Changing_Url_Clears' => 'ஸ்டோர் URL அல்லது API விசைகளை மாற்றுவது ஒவ்வொரு பொருத்தத்தையும் அழிக்கும் — தயாரிப்புகள், வகைகள், பிராண்டுகள் மற்றும் வாடிக்கையாளர்கள் அனைத்தும் புதிய ஸ்டோருடன் மீண்டும் ஒத்திசைக்கப்படும்.',
'Woo_Guide_Keep_Skus' => 'Stocky மற்றும் WooCommerce இடையே SKU-களை ஒரே மாதிரியாக வைத்திருங்கள்: அதுவே நகல்களைத் தடுக்கிறது, மீண்டும் இணைப்பதைப் பாதுகாப்பாக்குகிறது.',
'Woo_Guide_Stock_Total' => 'Woo-வில் வெளியிடப்படும் இருப்பு {total}, ஒரு கிடங்கின் எண்ணிக்கை அல்ல.',
