'Woo_Guide_Full_Reference' => 'முழுக் குறிப்பு — ஒவ்வொரு scope, queue எவ்வாறு செயல்படுகிறது, மற்றும் சிக்கல் தீர்க்கும் பட்டியல் — {file} இல் உள்ளது.',
'Woo_Way_Covers' => 'உள்ளடக்குவது',
