'Woo_Way_Covers_Scheduled' => 'அனைத்தும், இரு வழிகளிலும்: ஆர்டர்களும் தயாரிப்பு மாற்றங்களும் உள்ளே, பட்டியலும் இருப்பும் வெளியே',
'Woo_Way_Speed' => 'வேகம்',
'Woo_Way_Seconds' => 'வினாடிகள்',
'Woo_Way_Speed_Scheduled' => 'cron பதிவில் நீங்கள் வைப்பது எதுவோ அது (மணிநேர இருப்பு, ஒவ்வொரு 15 நிமிடத்திற்கும் ஆர்டர்கள்)',
'Woo_Way_Needs' => 'தேவை',
