'Woo_Way_Cron_Entries_Below' => 'கீழே உள்ள cron பதிவுகள்',
'Woo_Cron_Orders' => 'ஒவ்வொரு 15 நிமிடத்திற்கும் ஆர்டர்கள் — கடைசி ஓட்டத்திற்குப் பிறகு மாறியவை மட்டும்.',
'Woo_Cron_Products_Pull' => 'கடையிலிருந்து தயாரிப்பு மாற்றங்கள், இரவு 03:00 மணிக்கு.',
