'Woo_Cron_Stock' => 'ஒவ்வொரு மணிநேரமும் இருப்பு — உடனடி push-இன் கீழ் உள்ள பாதுகாப்பு வலை, அது இல்லாதபோது ஒரே இருப்பு ஒத்திசைவு.',
'Woo_Cron_Products_Push' => 'இன்னும் இணைக்கப்படாத தயாரிப்புகள், இரவு 02:00 மணிக்கு. ஏற்கனவே உள்ள தயாரிப்புகள் மீண்டும் எழுதப்படாது.',
'Woo_Cmd_Stock' => 'இணைக்கப்பட்ட ஒவ்வொரு தயாரிப்புக்கும் இப்போதே இருப்பை அனுப்பு.',
'Woo_Cmd_Products_Unsynced' => 'இன்னும் WooCommerce id இல்லாத தயாரிப்புகளை வெளியிடு.',
'Woo_Cmd_Orders' => 'கடைசி ஓட்டத்திற்குப் பிறகு மாறிய ஆர்டர்களை இறக்குமதி செய்.',
'Woo_Cmd_Orders_Full' => 'சமீபத்திய மாற்றங்களை மட்டுமல்லாமல் ஒவ்வொரு ஆர்டரையும் மீண்டும் ஸ்கேன் செய்.',
'Woo_Cmd_Pull' => 'உள்வரும் அனைத்தும் ஒரே நேரத்தில்: தயாரிப்புகள், ஆர்டர்கள், வாடிக்கையாளர்கள்.',
'Woo_Guide_Page_Title' => 'WooCommerce வழிகாட்டி',
'Woo_Guide_Page_Subtitle' => 'கடையை இணைத்தல், தானாக இயங்குபவை, மற்றும் இந்தச் சர்வருக்கான cron பதிவுகள்',
'Woo_Settings_Button' => 'WooCommerce அமைப்புகள்',
'Woo_No_Shop_Connected' => 'இன்னும் கடை எதுவும் இணைக்கப்படவில்லை',
'Woo_No_Shop_Connected_Desc' => 'கீழே உள்ள அனைத்தும் இன்னும் பொருந்தும் — WooCommerce அமைப்புகள் பக்கத்தில் ஸ்டோர் URL மற்றும் API விசைகளை உள்ளிட்டு, பின்னர் திரும்பி வாருங்கள்.',
'Woo_Wp_Username' => 'WordPress பயனர்பெயர்',
'Woo_Wp_App_Password' => 'WordPress application password',
'Woo_Settings_Instant_Hint' => 'ஒரு விற்பனை, திருப்பல் அல்லது சரிசெய்தல் சேமிக்கப்பட்ட உடனே அந்தத் தயாரிப்புகளுக்கு மட்டும் இருப்பு push அனுப்புகிறது, எனவே அடுத்த மணிநேர இருப்பு ஒத்திசைவுக்குப் பதிலாக வினாடிகளுக்குள் கடை சரியாகிவிடும். வேறு எதையும் நிறுவ வேண்டியதில்லை — விற்பனைக்குப் பதில் அளிக்கப்பட்ட பிறகு push இயங்குகிறது, எனவே கவுண்டர் ஒருபோதும் WooCommerce-க்காகக் காத்திருக்காது. மேலும் விவரங்கள் {guide} தாவலில்.',
'Woo_Settings_Instant_Off_Alert' => 'அணைத்து வைத்தால், ஒரு POS விற்பனை அடுத்த இருப்பு ஒத்திசைவில் மட்டுமே WooCommerce-ஐ அடையும் — ஒரு மணிநேரம் வரை தாமதமாக.',
'Woo_Settings_Auto_Products_Hint' => 'Stocky-இல் உருவாக்கப்பட்ட, திருத்தப்பட்ட அல்லது நகலெடுக்கப்பட்ட தயாரிப்பு சேமிக்கப்பட்ட உடனே WooCommerce-க்கு அனுப்பப்படும் — விவரங்கள், விலை, மாறுபாடுகள், படங்கள், பின்னர் அதன் இருப்பு — தயாரிப்பு ஒத்திசைவுக்காகக் காத்திருக்காமல். மொத்த இறக்குமதிகள் அனுப்பப்படுவதில்லை; இறக்குமதிக்குப் பிறகு தயாரிப்பு ஒத்திசைவை இயக்கவும்.',
'Woo_Sync_Tuning' => 'ஒத்திசைவுச் சீரமைப்பு',
'Woo_Sync_Tuning_Intro' => 'இயல்புநிலைகள் பெரும்பாலான ஸ்டோர்களுக்குப் பொருந்தும். உங்கள் ஹோஸ்டிங்கில் ஒத்திசைவு மெதுவாக இருந்தால் அல்லது நேரம் முடிந்தால் மட்டுமே இவற்றை மாற்றவும். ஒவ்வொரு மதிப்பும் பாதுகாப்பான வரம்புக்குள் கட்டுப்படுத்தப்படுகிறது, ஒரு புலத்தை அழிப்பது அதன் இயல்புநிலையை மீட்டெடுக்கும்.',
'Woo_Setting_This_Up' => 'இதை அமைத்தல்',
'Woo_Setting_This_Up_Text' => 'API விசைகளைப் பெறுதல், WordPress application password எதற்காக, திட்டமிட்ட ஒத்திசைவுகளுக்கான cron பதிவுகள், இருப்பு மாறிய உடனே கடையை அடையச் செய்வது எப்படி — இவை அனைத்தும், இந்தச் சர்வரின் சொந்த cron வரிகள் நகலெடுக்கத் தயாராக, வழிகாட்டி தாவலில் உள்ளன. ஒரே நகல், எனவே தொகுதி உண்மையில் செய்வதிலிருந்து அது விலகாது.',
