'Telegram_G_Own_Chat' => '{label} — முதலில் உங்கள் புதிய bot-க்கு ஏதேனும் ஒரு செய்தியை அனுப்பவும் (bot உரையாடலைத் தொடங்க முடியாது), பின்னர் {bot} க்குச் செய்தி அனுப்பவும்: அது உங்கள் பயனர் ID உடன் பதிலளிக்கும்.',
'Telegram_G_Your_Own_Chat' => 'உங்கள் சொந்த அரட்டை',
'Telegram_G_Group' => '{label} — bot-ஐக் குழுவில் சேர்த்து அதில் ஒரு செய்தியை இடவும்.',
'Telegram_G_A_Group' => 'ஒரு குழு',
'Telegram_G_Channel' => '{label} — bot-ஐச் சேனலின் {admin} ஆகச் சேர்த்து அதில் ஒரு செய்தியை இடவும்.',
'Telegram_G_A_Channel' => 'ஒரு சேனல்',
'Telegram_G_Administrator' => 'நிர்வாகி',
'Telegram_G_GetUpdates_Intro' => 'குழு அல்லது சேனலுக்கு, உங்கள் சொந்த டோக்கனுடன் இந்த முகவரியை உலாவியில் திறந்து, செய்தியை இட்ட பிறகு புதுப்பிக்கவும்:',
'Telegram_G_Chat_Id_Note' => '{json} ஐத் தேடவும். குழு அல்லது சேனல் ID எதிர்மறையானது, எ.கா. {example} — கழித்தல் குறி உட்பட முழுவதையும் நகலெடுக்கவும்.',
'Telegram_G_Step3_Title' => 'இங்கே இணைக்கவும்',
'Telegram_G_Step3_Body' => '{settings} தாவலில் bot டோக்கனையும் chat ID-ஐயும் ஒட்டி, {all} அல்லது நீங்கள் விரும்பும் {events} மட்டும் தேர்வு செய்து, {enable} ஐ இயக்கிச் சேமிக்கவும். பின்னர் {test} ஐ அழுத்தவும்.',
