'Telegram_G_State_Not_Configured' => 'இன்னும் உள்ளமைக்கப்படவில்லை',
'Telegram_G_Chat_Label' => 'அரட்டை {id}',
'Telegram_G_How_Sent' => 'செய்திகள் எவ்வாறு அனுப்பப்படுகின்றன',
'Telegram_G_A_Title' => 'உடனடியாக — எதையும் நிறுவ வேண்டியதில்லை',
'Telegram_G_A_Body' => 'Stocky-இல் — POS-இல் அல்லது நிர்வாகத்தில் — சேமிக்கப்படும் விற்பனை, கொள்முதல், கட்டணம் அல்லது செலவு, அதே கோரிக்கையில், சேமிக்கப்பட்ட {after} Telegram-க்கு அனுப்பப்படும். cron பதிவு இல்லை, queue worker இல்லை, காசாளர் ஒருபோதும் Telegram-க்காகக் காத்திருக்க மாட்டார்: செய்தி வெளியேறும்போது விற்பனைக்கு ஏற்கனவே பதில் அளிக்கப்பட்டிருக்கும்.',
'Telegram_G_Right_After' => 'உடனேயே',
'Telegram_G_B_Title' => 'cron பதிவு — மீண்டும் முயற்சிகளுக்கும் பின்னணி நிகழ்வுகளுக்கும்',
'Telegram_G_B_Body' => 'இரண்டு வகையான செய்திகள் Telegram-இன் சொந்த queue-இல் காத்திருக்கின்றன: தோல்வியடைந்த அனுப்புதல் (Telegram சிறிது நேரம் அணுக முடியாதபோது), இது அடுத்த சில நிமிடங்களில் இன்னும் மூன்று முறை வரை மீண்டும் முயற்சிக்கப்படும்; மற்றும் நிர்வாகத்திற்கு வெளியே எழும் நிகழ்வுகள் — WooCommerce அல்லது Shopify-இலிருந்து இறக்குமதி செய்யப்பட்ட ஆர்டர்கள், artisan கட்டளைகள். இந்த cron பதிவு அவற்றை அனுப்புகிறது, வேறு எதையும் அல்ல:',
'Telegram_G_Cron_Note' => 'ஒவ்வொரு நிமிடமும் சரியானது: காத்திருக்க எதுவும் இல்லாத ஓட்டம் உடனே வெளியேறும். cPanel-இல் இது {cronJobs} இல் செல்லும் — {php} பழையதாக இருந்தால் PHP 8.2+ க்கான முழுப் பாதையைப் பயன்படுத்தவும். Windows-இல், Task Scheduler-ஐ நிரல் {program}, arguments {args} உடன் {path} இல் தொடங்கிப் பயன்படுத்தவும்.',
'Telegram_G_Waiting' => '{n} அனுப்பக் காத்திருக்கின்றன',
