'Telegram_G_Growing_Note' => '— இந்த எண் தொடர்ந்து அதிகரித்தால், cron பதிவு இயங்கவில்லை.',
'Telegram_G_Without_Cron' => 'cron பதிவு இல்லாவிட்டாலும், Stocky-இல் சேமிக்கப்படும் அனைத்தும் உடனடியாக வந்துசேரும்; மீண்டும் முயற்சிகளையும் இறக்குமதி செய்யப்பட்ட ஆர்டர்களையும் மட்டுமே இழப்பீர்கள்.',
