'Integ_Desc_Shopify' => 'Shopify உடன் தயாரிப்புகள், சரக்கு, ஆர்டர்கள் மற்றும் வாடிக்கையாளர்களின் பல-ஸ்டோர் ஒத்திசைவு.',
'Integ_Desc_Salla' => 'தயாரிப்புகள், இருப்பு மற்றும் ஆர்டர்களை உங்கள் Salla ஸ்டோருடன் ஒத்திசைக்கவும் (வளைகுடா மின்வணிகம்).',
'Integ_Desc_PrestaShop' => 'தயாரிப்புகள், இருப்பு மற்றும் ஆர்டர்களை உங்கள் PrestaShop ஸ்டோருடன் ஒத்திசைக்கவும்.',
'Integ_Desc_Jumia' => 'விலைகளையும் இருப்பையும் Jumia Seller Center-க்கு அனுப்பி, சந்தை ஆர்டர்களை இறக்குமதி செய்யவும்.',
