'WhatsApp_G5' => '{title} ஒரு பச்சைப் பெட்டி உங்கள் சரிபார்க்கப்பட்ட பெயரையும் எண்ணையும் காட்டும். ஒரு சிவப்புப் பெட்டி Meta எதை நிராகரித்தது, அதை எப்படிச் சரிசெய்வது என்பதைத் துல்லியமாகக் கூறும்.',
