'WhatsApp_G6' => '{title} WhatsApp → {configuration} → Webhook → {edit}: இந்தப் பக்கத்திலிருந்து {callback} மற்றும் {verifyToken} ஐ ஒட்டவும் → {verifySave}. பின்னர் {manage} ஐக் கிளிக் செய்து {messages} க்குச் சந்தா செய்யவும். Meta சரிபார்த்தவுடன் இந்தப் பக்கத்தில் உள்ள "{lastCall}" பெட்டி புதுப்பிக்கப்படும்.',
'WhatsApp_G6_Title' => 'webhook-ஐப் பதிவுசெய்யவும்.',
'WhatsApp_G7' => '{title} படி 3 இலிருந்து உங்கள் சொந்த எண்ணுக்கு. மேம்பாட்டுப் பயன்முறையில் அந்த எண் முதலில் API Setup → "To" இன் கீழ் சேர்க்கப்பட வேண்டும். டெலிவரிக் குறிகள் (sent → delivered → read) பதிவில் தோன்றும்.',
'WhatsApp_G7_Title' => 'சோதனைச் செய்தியை அனுப்பவும்',
'WhatsApp_G8' => '{title} {enable} ஐ இயக்கி, பின்னர் நீங்கள் விரும்பும் தானியக்கங்களைத் தேர்வு செய்யவும். விற்பனைகள், மேற்கோள்கள் மற்றும் கொள்முதல்களுக்கு WhatsApp Web-ஐத் திறப்பதற்குப் பதிலாக API மூலம் அனுப்பும் நேரடி "WhatsApp" செயலும் கிடைக்கும்.',
'WhatsApp_G8_Title' => 'நேரலைக்குச் செல்லவும்.',
