'Salla_Customers_Linked' => 'இணைக்கப்பட்ட வாடிக்கையாளர்கள்',
'Salla_Pull_Orders_From' => '{name} இலிருந்து ஆர்டர்களைப் பெறு',
'Salla_Pull_Orders_Desc' => 'புதிய Salla ஆர்டர்கள் பொதுவாக webhooks மூலம் தானாக வந்து விற்பனைகளாகின்றன. webhook அமைக்கப்படுவதற்கு முன் வைக்கப்பட்ட ஆர்டர்களை நிரப்ப இந்தப் பெறுதலைப் பயன்படுத்தவும் — ஏற்கனவே இறக்குமதி செய்யப்பட்ட ஆர்டர்கள் தவிர்க்கப்படும்.',
