'Salla_Clear_Logs' => 'பதிவுகளை அழி',
'Salla_Guide_1' => '{link} இல் ஒரு (தனிப்பட்ட) ஆப்பை உருவாக்கி {mode} அங்கீகாரப் பாய்வைத் தேர்வு செய்யவும்.',
'Salla_Guide_2' => 'ஆப்பின் {clientId} மற்றும் {clientSecret} ஐ இணைப்புத் தாவலில் நகலெடுத்துச் சேமிக்கவும்.',
'Salla_Guide_3' => 'ஆப்பின் அமைப்புகளில், இணைப்புத் தாவலில் காட்டப்படும் OAuth callback URL-ஐ அமைக்கவும்.',
'Salla_Guide_4' => 'ஆப்பின் Webhooks பக்கத்தில்: {signature} பாதுகாப்பு உத்தியைத் தேர்வு செய்து, அதன் secret-ஐ இங்குள்ள Webhook Secret புலத்தில் நகலெடுத்து, இணைப்புத் தாவலில் காட்டப்படும் Webhook URL-ஐ அமைத்து, குறைந்தது {e1}, {e2}, {e3}, {e4}, {e5} மற்றும் {e6} க்குச் சந்தா செய்யவும்.',
'Salla_Guide_5' => '{connect} ஐக் கிளிக் செய்து உங்கள் ஸ்டோரில் ஆப்பை அங்கீகரிக்கவும். (Easy Mode இல் உள்ள ஆப்கள் அதற்குப் பதிலாக {webhook} webhook மூலம் தானாக இணைகின்றன.)',
'Salla_Guide_6' => 'தயாரிப்புகளைப் பெறவும் அல்லது அனுப்பவும், பின்னர் இருப்பை அனுப்பவும். புதிய ஆர்டர்கள் தானாக வந்து {ref} போன்ற குறிப்புகளுடன் விற்பனைகளின் கீழ் தோன்றும்.',
'Salla_Identity_Sku_Title' => 'தயாரிப்பின் அடையாளம் SKU ஆகும்',
'Salla_Identity_Sku_Desc' => 'Stocky-இன் தயாரிப்புக் குறியீடு Salla-வின் SKU உடன் பொருத்தப்படுகிறது. இரு பக்கங்களிலும் SKU-களை ஒரே மாதிரியாக வைத்திருங்கள்; மாறுபாடுள்ள தயாரிப்புகள் பெறுதலிலும் ஆர்டர்களிலும் பொருத்தப்படுகின்றன, ஆனால் இந்தப் பதிப்பில் அனுப்பப்படுவதில்லை.',
