'Presta_Shop_Language_Id' => 'கடை மொழி ID',
'Presta_Shop_Language_Help' => 'அனுப்பும்போது தயாரிப்புப் பெயர்களுக்குப் பயன்படுத்தப்படும் மொழி id (1 = கடையின் முதல் மொழி).',
'Presta_Push_Products_Desc' => 'PrestaShop-இல் இல்லாத எளிய தயாரிப்புகளை (அவற்றின் தற்போதைய இருப்புடன்) உருவாக்குகிறது. ஏற்கனவே இணைக்கப்பட்ட தயாரிப்புகளும் மாறுபாடுள்ள தயாரிப்புகளும் தவிர்க்கப்படும் — தயாரிப்பு விவரங்களை PrestaShop-இல் தொடர்ந்து திருத்தவும், அல்லது உள்ளூர் நகலைப் புதுப்பிக்கப் பெறவும்.',
'Presta_Pull_Products_Desc' => 'PrestaShop தயாரிப்புகளை இறக்குமதி செய்கிறது, ஏற்கனவே உள்ளவற்றை reference (SKU) மூலம் பொருத்தி மீதமுள்ளவற்றை உருவாக்குகிறது. Combinations அவற்றின் தாய்த் தயாரிப்பாக இறக்குமதி செய்யப்படுகின்றன.',
'Presta_Reset_Product_Confirm' => 'தயாரிப்பு இணைப்புகளை மீட்டமைக்கவா? ஆர்டர் வரலாறு அதன் இணைப்புகளை வைத்திருக்கும்.',
'Presta_Push_Stock_Desc' => 'இணைக்கப்பட்ட ஒவ்வொரு தயாரிப்புக்கும் கடையின் இருப்பை (stock_availables) புதுப்பிக்கிறது.',
'Presta_Pull_Orders_Desc' => 'கடை ஆர்டர்களை விற்பனைகளாக இறக்குமதி செய்கிறது ({ref} போன்ற குறிப்புகள்), புதியவை முதலில். ஏற்கனவே இறக்குமதி செய்யப்பட்ட மற்றும் ரத்துசெய்யப்பட்ட ஆர்டர்கள் தவிர்க்கப்படும், எனவே தொடர்ந்து பெறுவது பாதுகாப்பானது. PrestaShop-இல் webhooks இல்லை — பரபரப்பான காலங்களுக்குப் பிறகு இதை இயக்கவும்.',
'Presta_Guide_1' => 'உங்கள் PrestaShop back office-இல் {menu} ஐத் திறந்து webservice-ஐ இயக்கவும்.',
'Presta_Guide_2' => 'புதிய விசையைச் சேர்த்து, {products} மற்றும் {stock} மீது {rw}, {orders} மற்றும் {customers} மீது {view} அனுமதி வழங்கவும்.',
'Presta_Guide_3' => 'ஸ்டோர் URL-ஐயும் விசையையும் இணைப்புத் தாவலில் ஒட்டிச் சேமித்து, {test} ஐ இயக்கவும்.',
'Presta_Guide_4' => 'கடையில் ஏற்கனவே பட்டியல் இருந்தால் முதலில் தயாரிப்புகளைப் பெறவும் (reference/SKU மூலம் பொருத்தும்); இல்லாத எளிய தயாரிப்புகளை உருவாக்க அனுப்பவும்.',
'Presta_Guide_5' => 'அளவுகள் மாறும்போதெல்லாம் இருப்பை அனுப்பவும், ஆர்டர்களைத் தொடர்ந்து பெறவும் — PrestaShop-இல் webhooks இல்லை, எனவே நீங்கள் பெறும்போது மட்டுமே ஆர்டர்கள் வரும்.',
'Presta_Identity_Title' => 'தயாரிப்பின் அடையாளம் reference (SKU) ஆகும்',
'Presta_Identity_Desc' => 'Stocky-இன் தயாரிப்புக் குறியீடு PrestaShop-இன் reference உடன் பொருத்தப்படுகிறது. இரு பக்கங்களிலும் references-ஐ ஒரே மாதிரியாக வைத்திருங்கள்; combinations (மாறுபாடுகள்) ஆர்டர்களில் reference மூலம் பொருத்தப்படுகின்றன, ஆனால் இந்தப் பதிப்பில் அனுப்பப்படுவதில்லை.',
'Xero_Hero_Title' => 'Xero கணக்கியல் ஒத்திசைவு',
'Xero_Hero_Desc' => 'உங்கள் வாடிக்கையாளர்களை Xero தொடர்புகளாகவும் உங்கள் விற்பனைகளை விலைப்பட்டியல்களாகவும் அனுப்பவும் — வங்கிக் கணக்கு உள்ளமைக்கப்பட்டிருந்தால் கட்டணங்களுடன்.',
'Xero_App_Credentials_Accounts' => 'ஆப் நற்சான்றுகள் & கணக்குகள்',
'Xero_From_Dev_App' => 'developer.xero.com இல் உள்ள உங்கள் ஆப்பிலிருந்து',
'Xero_Sales_Account_Code' => 'விற்பனைக் கணக்குக் குறியீடு',
'Xero_Sales_Account_Help' => 'விலைப்பட்டியல் வரிகளுக்கான வருவாய்க் கணக்கு (\'200\' என்பது Xero-வின் இயல்புநிலை Sales கணக்கு).',
'Xero_Payment_Account_Code' => 'கட்டணக் கணக்குக் குறியீடு (விருப்பத்தேர்வு)',
'Xero_Payment_Account_Ph' => 'எ.கா. 090',
'Xero_Payment_Account_Help' => 'ஒரு வங்கிக் கணக்குக் குறியீடு. அமைக்கப்பட்டால், செலுத்தப்பட்ட விற்பனைகள் விலைப்பட்டியலில் கட்டணத்தையும் பதிவுசெய்யும்; விலைப்பட்டியல்களை மட்டும் ஒத்திசைக்க காலியாக விடவும்.',
'Xero_Auto_Sync_Sales' => 'புதிய விற்பனைகளை விலைப்பட்டியல்களாகத் தானாக ஒத்திசை',
'Xero_Auto_Sync_Sales_Hint' => '(விற்பனைகள் உருவாக்கப்படும்போது பின்னணியில் வரிசைப்படுத்தப்படும்)',
'Xero_Org_Connection' => 'நிறுவன இணைப்பு',
'Xero_Organisation' => 'நிறுவனம்',
'Xero_Disconnect_Confirm' => 'Xero நிறுவனத்தைத் துண்டிக்கவா? நீங்கள் மீண்டும் இணைக்கும் வரை ஒத்திசைவு நிற்கும்.',
'Xero_Redirect_Uri_Title' => 'Xero ஆப்புக்கான Redirect URI',
'Xero_Redirect_Uri_Help' => '{link} இல் ஒரு "Web app" ஐ உருவாக்கி இந்த redirect URI-ஐப் பதிவுசெய்யவும். குறிப்பு: Xero அணுகல் டோக்கன்கள் தானாகப் புதுப்பிக்கப்படும், ஆனால் 60 நாட்களுக்கு மேல் செயலற்ற இணைப்பை மீண்டும் இணைக்க வேண்டும்.',
'Xero_Total_Customers' => 'மொத்த வாடிக்கையாளர்கள்',
'Xero_Contacts_In_Xero' => 'Xero-வில் உள்ள தொடர்புகள்',
'Xero_Total_Sales' => 'மொத்த விற்பனைகள்',
'Xero_Invoices_In_Xero' => 'Xero-வில் உள்ள விலைப்பட்டியல்கள்',
'Xero_Payments_Recorded' => 'பதிவுசெய்யப்பட்ட கட்டணங்கள்',
'Xero_Push_Customers_To' => 'வாடிக்கையாளர்களை {name} க்கு அனுப்பு',
'Xero_Push_Customers_Desc' => 'ஒவ்வொரு வாடிக்கையாளருக்கும் ஒரு Xero தொடர்பை உருவாக்குகிறது அல்லது புதுப்பிக்கிறது. பெயர் ஏற்கனவே Xero-வில் உள்ள வாடிக்கையாளர் அந்தத் தொடர்புடன் இணைக்கப்படுவார்.',
'Xero_Push_Customers' => 'வாடிக்கையாளர்களை அனுப்பு',
'Xero_Push_Sales_Invoices' => 'விற்பனைகளை விலைப்பட்டியல்களாக அனுப்பு',
'Xero_Push_Invoices_Desc' => 'ஒவ்வொரு விற்பனைக்கும் ஒரு AUTHORISED விலைப்பட்டியலை உருவாக்குகிறது (விலைப்பட்டியல் எண் = விற்பனை Ref), விற்பனையின் வரி உருப்படிகளுடன் கப்பல், தள்ளுபடி மற்றும் வரி வரிகளையும் சேர்த்து, Xero மொத்தம் விற்பனை மொத்தத்துடன் பொருந்தும்படி. ஏற்கனவே Xero-வில் உள்ள விற்பனைகள் தவிர்க்கப்படும் — விலைப்பட்டியல்கள் ஒருபோதும் திருத்தப்படாது. இல்லாத தொடர்புகள் உடனுக்குடன் உருவாக்கப்படும்.',
'Xero_Push_Invoices' => 'விலைப்பட்டியல்களை அனுப்பு',
'Xero_Reset_Contact_Confirm' => 'தொடர்பு இணைப்புகளை மீட்டமைக்கவா? அடுத்த அனுப்புதல் அவற்றை மீண்டும் இணைக்கும் அல்லது மீண்டும் உருவாக்கும்.',
'Xero_Reset_Contact_Links' => 'தொடர்பு இணைப்புகளை மீட்டமை',
'Xero_Guide_1' => '{link} இல் ஒரு {webApp} ஐ உருவாக்கவும் ({menu}).',
'Xero_Guide_2' => 'இணைப்புத் தாவலில் காட்டப்படும் redirect URI-ஐப் பதிவுசெய்யவும்.',
'Xero_Guide_3' => 'ஆப்பின் {clientId} ஐ நகலெடுத்து ஒரு {clientSecret} ஐ உருவாக்கவும்; இரண்டையும் இங்கே ஒட்டிச் சேமிக்கவும்.',
'Xero_Guide_4' => '{connect} ஐக் கிளிக் செய்து, உள்நுழைந்து, இணைக்க வேண்டிய நிறுவனத்தைத் தேர்வு செய்யவும்.',
'Xero_Guide_5' => 'கணக்குக் குறியீடுகளைச் சரிபார்க்கவும்: விற்பனைக் கணக்கு விலைப்பட்டியல் வரிகளைப் பெறும்; செலுத்தப்பட்ட விற்பனைகள் கட்டணங்களையும் பதிவுசெய்ய வேண்டுமெனில் வங்கிக் கணக்குக் குறியீட்டை அமைக்கவும்.',
'Xero_Guide_6' => 'முதலில் வாடிக்கையாளர்களை அனுப்பவும், பின்னர் விலைப்பட்டியல்களை. விலைப்பட்டியல் எண்கள் விற்பனை Ref-கள், எனவே இணைப்புகள் மீட்டமைக்கப்பட்டாலும் நகல்கள் Xero ஆல் நிராகரிக்கப்படும்.',
'Xero_Amounts_Title' => 'தொகைகள் வரி உட்பட அப்படியே அனுப்பப்படுகின்றன',
'Xero_Amounts_Desc' => 'விலைப்பட்டியல்கள் விற்பனையைச் சரியாகப் பிரதிபலிக்கும் NoTax வரிகளைப் பயன்படுத்துகின்றன (பொருட்கள் + கப்பல் − தள்ளுபடி + வரி), எனவே Xero மொத்தங்கள் எப்போதும் Stocky மொத்தங்களுக்குச் சமம். உங்கள் கணக்காளர் வரி மற்றும் கப்பல் வரிகளை Xero-வில் சரியான கணக்குகளுக்கு மறுவரைபடமாக்கலாம்.',
'Xero_Org_Connected' => 'Xero நிறுவனம் இணைக்கப்பட்டது.',
'Jumia_Hero_Title' => 'Jumia சந்தை ஒத்திசைவு',
'Jumia_Hero_Desc' => 'விலைகளையும் இருப்பையும் உங்கள் Jumia Seller Center பட்டியல்களுக்கு அனுப்பி, சந்தை ஆர்டர்களை விற்பனைகளாக இறக்குமதி செய்யவும்.',
'Jumia_Api_Url_Label' => 'API URL (உங்கள் நாட்டின் Seller Center endpoint)',
'Jumia_Account_Email' => 'கணக்கு மின்னஞ்சல் (User ID)',
'Jumia_Api_Key' => 'API விசை',
'Jumia_Prices_Stock' => 'விலைகள் & இருப்பு',
'Jumia_Push_Prices_Stock_Title' => 'விலைகளையும் இருப்பையும் Jumia-க்கு அனுப்பு',
'Jumia_Push_Prices_Stock_Desc' => 'Jumia பட்டியலின் {sku} உடன் பொருந்தும் SKU உள்ள ஒவ்வொரு தயாரிப்புக்கும் (மற்றும் மாறுபாட்டுக்கும்) தற்போதைய விலையையும் அளவையும் அனுப்புகிறது. புதுப்பிப்புகள் Seller Center feeds ஆகச் சமர்ப்பிக்கப்பட்டு ஒத்திசைவற்ற முறையில் பயன்படுத்தப்படுகின்றன — feed ID பதிவுகள் தாவலில் பதிவுசெய்யப்படும், ஒவ்வொரு உருப்படியின் நிராகரிப்புகளும் Seller Center-இன் feed நிலைத் திரையில் தோன்றும்.',
'Jumia_Push_Prices_Stock' => 'விலைகளையும் இருப்பையும் அனுப்பு',
'Jumia_Pull_Orders_Desc' => 'சந்தை ஆர்டர்களை விற்பனைகளாக இறக்குமதி செய்கிறது ({ref} போன்ற குறிப்புகள்), Seller SKU மூலம் உங்கள் தயாரிப்புகளுடன் பொருத்தப்படுகின்றன. ஏற்கனவே இறக்குமதி செய்யப்பட்ட மற்றும் ரத்துசெய்யப்பட்ட ஆர்டர்கள் தவிர்க்கப்படும், எனவே தொடர்ந்து பெறுவது பாதுகாப்பானது. டெலிவரி செய்யப்பட்ட ஆர்டர்களுக்கு மட்டுமே கட்டணங்கள் செலுத்தப்பட்டதாகக் குறிக்கப்படும் (Jumia பெரும்பாலும் COD).',
'Jumia_Guide_1' => 'Jumia {sellerCenter} இல் {menu} ஐத் திறந்து ஒரு API விசையை உருவாக்கவும்.',
'Jumia_Guide_2' => 'உங்கள் நாட்டின் API URL (எ.கா. நைஜீரியாவுக்கு {ng}, கென்யாவுக்கு {ke}, எகிப்துக்கு {eg}), உங்கள் Seller Center கணக்கு மின்னஞ்சல் மற்றும் விசையை உள்ளிடவும் — பின்னர் {test} ஐ இயக்கவும்.',
'Jumia_Guide_3' => 'ஒவ்வொரு Jumia பட்டியலின் {sku} உம் Stocky தயாரிப்புக் குறியீட்டுக்குச் சமமாக இருப்பதை உறுதிசெய்யவும் — இருப்பு அனுப்புதல் மற்றும் ஆர்டர் பொருத்தம் இரண்டுக்கும் பயன்படும் அடையாளம் அதுவே.',
'Jumia_Guide_4' => 'சரக்கு மாற்றங்களுக்குப் பிறகு விலைகளையும் இருப்பையும் அனுப்பவும்; ஆர்டர்களைத் தொடர்ந்து பெறவும் (இந்த API-இல் Jumia-க்கு webhooks இல்லை).',
'Jumia_Guide_5' => 'புதிய பட்டியல்களை உருவாக்குவது Seller Center-இலேயே இருக்கும் — Jumia-க்கு வகை-சார்ந்த பண்புகளும் பட மதிப்பாய்வும் தேவை, அவற்றை அவர்களின் போர்டல் மட்டுமே சரியாகக் கையாள்கிறது.',
'Mailchimp_Hero_Title' => 'Mailchimp பார்வையாளர் ஒத்திசைவு',
'Mailchimp_Hero_Desc' => 'உங்கள் உண்மையான வாடிக்கையாளர் தளத்தில் மின்னஞ்சல் பிரச்சாரங்களை இயக்க, ஒரு Mailchimp பார்வையாளர் பட்டியலை உங்கள் வாடிக்கையாளர்களால் நிரப்பி வைத்திருங்கள்.',
'Mailchimp_Account_Audience' => 'கணக்கு & பார்வையாளர்கள்',
'Mailchimp_Api_Key_Ph' => 'எ.கா. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} உறுப்பினர்கள்)',
'Mailchimp_Load_Audiences_Ph' => 'ஒன்றைத் தேர்வு செய்ய பார்வையாளர் பட்டியல்களை ஏற்றவும்',
'Mailchimp_Load_Audiences' => 'பார்வையாளர் பட்டியல்களை ஏற்று',
'Mailchimp_Double_Optin_Label' => 'இரட்டை ஒப்புதல் — புதிய உறுப்பினர்கள் சேர்வதற்கு முன் உறுதிப்படுத்தல் மின்னஞ்சலைப் பெறுவார்கள்',
'Mailchimp_Double_Optin_Hint' => '(GDPR-க்குப் பரிந்துரைக்கப்படுகிறது)',
'Mailchimp_Auto_Sync_Customers' => 'புதிய வாடிக்கையாளர்கள் உருவாக்கப்படும்போதே தானாக ஒத்திசை',
'Mailchimp_With_Email' => 'மின்னஞ்சலுடன்',
'Mailchimp_Push_Desc' => 'மின்னஞ்சல் முகவரி உள்ள ஒவ்வொரு வாடிக்கையாளரையும் (பெயர் மற்றும் தொலைபேசி உட்பட) தேர்ந்தெடுத்த பார்வையாளர் பட்டியலில் சேர்க்கிறது அல்லது புதுப்பிக்கிறது. ஏற்கனவே உள்ள உறுப்பினர்கள் தங்கள் சந்தா நிலையை வைத்திருப்பார்கள் — சந்தா நீக்கிய யாரும் மீண்டும் சந்தா செய்யப்பட மாட்டார்கள். மின்னஞ்சல் இல்லாத வாடிக்கையாளர்கள் விலக்கப்படுவார்கள்.',
'Mailchimp_Double_Optin_Off_Title' => 'இரட்டை ஒப்புதல் அணைப்பில் உள்ளது',
'Mailchimp_Double_Optin_Off_Desc' => 'புதிய உறுப்பினர்கள் உறுதிப்படுத்தல் மின்னஞ்சல் இல்லாமல் சந்தாதாரர்களாகச் சேர்க்கப்படுவார்கள். மார்க்கெட்டிங்கைப் பெற ஏற்கனவே ஒப்புக்கொண்ட வாடிக்கையாளர்களுக்கு மட்டுமே இதைச் செய்யவும்.',
'Mailchimp_Guide_1' => 'Mailchimp-இல் {menu} ஐத் திறந்து ஒரு விசையை உருவாக்கவும் (அது {suffix} இல் முடியும் — அந்த பின்னொட்டே உங்கள் datacenter).',
'Mailchimp_Guide_2' => 'விசையை இங்கே ஒட்டிச் சேமித்து, பின்னர் {load} ஐக் கிளிக் செய்து நிரப்ப வேண்டிய பார்வையாளர் பட்டியலைத் தேர்வு செய்யவும்.',
'Mailchimp_Guide_3' => 'உங்கள் வாடிக்கையாளர்கள் ஏற்கனவே மார்க்கெட்டிங் மின்னஞ்சல்களுக்கு ஒப்புதல் அளித்திருந்தால் தவிர {doubleOptIn} ஐ இயக்கத்திலேயே வைத்திருங்கள்.',
'Mailchimp_Double_Optin_Term' => 'இரட்டை ஒப்புதல்',
'Mailchimp_Guide_4' => 'ஆரம்ப நிரப்புதலுக்கு {push} ஐ இயக்கவும்; புதிய வாடிக்கையாளர்கள் தானாகச் சேர {autoSync} ஐ இயக்கவும்.',
'Mailchimp_Auto_Sync_Term' => 'தானியங்கி ஒத்திசைவு',
'Mailchimp_Consent_Title' => 'ஒப்புதல் முக்கியம்',
'Mailchimp_Consent_Desc' => 'மார்க்கெட்டிங்கிற்கு ஒருபோதும் ஒப்புக்கொள்ளாதவர்களுக்கு மின்னஞ்சல் அனுப்புவது GDPR/CAN-SPAM-ஐ மீறலாம், உங்கள் Mailchimp கணக்கு இடைநிறுத்தப்படலாம். இரட்டை ஒப்புதல் உறுதிப்படுத்தலை Mailchimp-க்கு மாற்றுகிறது — பாதுகாப்பான இயல்புநிலை.',
'Mailchimp_No_Audiences' => 'இந்தக் கணக்கில் பார்வையாளர் பட்டியல்கள் எதுவும் இல்லை.',
'GSheets_Hero_Title' => 'Google Sheets ஏற்றுமதிகள்',
'GSheets_Hero_Desc' => 'உங்கள் விற்பனைகள், தயாரிப்புகள் மற்றும் வாடிக்கையாளர்களை நேரலை Google விரிதாளுக்கு ஏற்றுமதி செய்யவும் — ஒவ்வொன்றுக்கும் ஒரு தாவல், தேவைக்கேற்பப் புதுப்பிக்கப்படும்.',
