'GSheets_Client_Secret_Ph' => 'உங்கள் Google Cloud OAuth client-இலிருந்து',
'GSheets_Auto_Export' => 'ஒவ்வொரு இரவும் தானாக ஏற்றுமதி',
'GSheets_Auto_Export_Hint' => '(அனைத்துத் தாவல்களும் சர்வர் நேரப்படி சுமார் 02:30 மணிக்குப் புதுப்பிக்கப்படும்)',
'GSheets_Enable' => 'Google Sheets ஏற்றுமதிகளை இயக்கு',
'GSheets_Account_Spreadsheet' => 'கணக்கு & விரிதாள்',
'GSheets_Reconnect_Account' => 'Google கணக்கை மீண்டும் இணை',
'GSheets_Connect_Account' => 'Google கணக்கை இணை',
'GSheets_Disconnect_Confirm' => 'Google கணக்கைத் துண்டிக்கவா? நீங்கள் மீண்டும் இணைக்கும் வரை ஏற்றுமதிகள் நிற்கும்.',
'GSheets_Target_Spreadsheet' => 'இலக்கு விரிதாள் (ID அல்லது முழு URL)',
'GSheets_Spreadsheet_Ph' => 'ஒரு விரிதாள் URL-ஐ ஒட்டவும், அல்லது ஒன்றை உருவாக்கவும் →',
'GSheets_Create_New' => 'புதியதை உருவாக்கு',
'GSheets_Open_Spreadsheet' => 'விரிதாளைத் திற',
'GSheets_Last_Export' => 'கடைசி ஏற்றுமதி {date}',
'GSheets_Redirect_Uri_Title' => 'Google OAuth client-க்கான Redirect URI',
'GSheets_Export_Desc' => 'ஒவ்வொரு ஏற்றுமதியும் அதன் தாவலை முதலிலிருந்து மீண்டும் எழுதுகிறது (தலைப்பு + அனைத்து வரிசைகளும்), எனவே தாள் எப்போதும் முழுமையான, தற்போதைய நிலைப்படமாக இருக்கும். பெரிய தரவுத்தொகுப்புகள் தொகுதிகளாக அனுப்பப்படுகின்றன — எண்ணி நிற்கும் வரை பக்கத்தைத் திறந்தே வைக்கவும்.',
'GSheets_Export_Sales' => 'விற்பனைகளை ஏற்றுமதி செய்',
'GSheets_Export_Products' => 'தயாரிப்புகளை ஏற்றுமதி செய்',
'GSheets_Export_Customers' => 'வாடிக்கையாளர்களை ஏற்றுமதி செய்',
'GSheets_Sales_Desc' => 'வாடிக்கையாளர், மொத்தங்கள், கட்டண நிலை மற்றும் கிடங்குடன் ஒவ்வொரு விற்பனையும்.',
'GSheets_Products_Desc' => 'விலைகள், செலவுகள் மற்றும் தற்போதைய இருப்பு அளவுகளுடன் முழுப் பட்டியல்.',
'GSheets_Customers_Desc' => 'அனைத்து வாடிக்கையாளர்களும் அவர்களின் தொடர்பு விவரங்களுடன்.',
'GSheets_Guide_1' => '{link} இல் ஒரு project-ஐ உருவாக்கி {api} ஐ இயக்கவும் ({menu}).',
'GSheets_Guide_2' => '{consent} ஐ உள்ளமைக்கவும் (External). அது "Testing" இல் இருக்கும் வரை, உங்கள் Google கணக்கைச் சோதனைப் பயனராகச் சேர்க்கவும் — testing-mode refresh tokens 7 நாட்களுக்குப் பிறகு காலாவதியாகும் என்பதைக் கவனிக்கவும், எனவே நிரந்தர இணைப்புக்கு ஆப்பை {publish}.',
'GSheets_Publish' => 'வெளியிடவும்',
'GSheets_Guide_3' => 'Web application வகையிலான ஒரு {clientId} ஐ உருவாக்கி, இணைப்புத் தாவலில் காட்டப்படும் redirect URI-ஐப் பதிவுசெய்யவும்.',
'GSheets_Guide_4' => 'Client ID மற்றும் Secret-ஐ இங்கே ஒட்டிச் சேமித்து, {connect} ஐக் கிளிக் செய்யவும்.',
'GSheets_Guide_5' => 'பொத்தானைக் கொண்டு ஒரு விரிதாளை உருவாக்கவும் (அல்லது உங்கள் Google கணக்கு திருத்தக்கூடிய ஒன்றின் URL-ஐ ஒட்டவும்), பின்னர் ஏற்றுமதிகளை இயக்கவும்.',
'GSheets_Snapshots_Title' => 'நிலைப்படங்கள், நேரலை ஒத்திசைவு அல்ல',
'GSheets_Snapshots_Desc' => 'ஏற்றுமதிகள் Sales / Products / Customers தாவல்களைத் தேவைக்கேற்ப மீண்டும் எழுதுகின்றன. ஒவ்வொரு விற்பனைக்கும் வரிசை-வாரியான நேரலைப் புதுப்பிப்புகளுக்கு Zapier-ஐ இணைக்கவும் — நிகழ்வுகள் நடந்தவுடன் அது வரிசைகளைச் சேர்க்கும்.',
