'Shopify_Auto_On_Note' => '{cmd} ஐ இயக்கும் cron பதிவால் இயக்கப்படுகிறது — அது இல்லாவிட்டால், இங்கே எதுவும் தானாக இயங்காது. கைமுறை ஒத்திசைவும் ஒரு ஓட்டமாகக் கணக்கிடப்படும்: அது அடுத்ததைப் படியின் இடைவெளி அளவுக்குத் தள்ளிவைக்கும்.',
