'Shopify_Stock_Lag_Desc' => 'அதுவரை கவுண்டரில் நடக்கும் விற்பனை கடைக்குத் தெரியாது — {n} நிமிடங்கள் வரை, எனவே கடைசி அலகு ஆன்லைனில் இருமுறை விற்கப்படக்கூடும். {setting} ஐ இயக்கினால், ஒவ்வொரு விற்பனை, திருப்பல் மற்றும் சரிசெய்தலும் வினாடிகளுக்குள் அனுப்பப்படும்.',
'Shopify_Turn_It_On' => 'இயக்கு',
'Shopify_Stock_Also_Pushed' => 'மேலே உள்ள படிக்காகக் காத்திருக்காமல், எந்த விற்பனை, திருப்பல் அல்லது சரிசெய்தலுக்குப் பிறகும் வினாடிகளுக்குள் இருப்பு அனுப்பப்படும்.',
