'Shopify_Nothing_Run_Store' => 'இந்த ஸ்டோருக்கு எதுவும் இயங்கவில்லை',
'Shopify_Hook_Msg_Client' => 'கீழே உள்ள “Register webhooks” ஐக் கிளிக் செய்யவும் — Shopify-இல் எதையும் உள்ளிட வேண்டியதில்லை.',
'Shopify_Hook_Msg_Token' => 'கீழே உள்ள “Register webhooks” ஐக் கிளிக் செய்து, ஆப்பின் API secret key-ஐ ஸ்டோர் அமைப்புகளில் கையொப்ப secret ஆக ஒட்டவும்.',
'Shopify_Hook_Note_Register' => 'பதிவுசெய்வது Shopify-இல் சந்தாக்களை உருவாக்கி அவற்றைத் தானாக இந்த முகவரிக்குச் சுட்டுகிறது. Shopify → Settings → Notifications → Webhooks இன் கீழ் இதைக் கைமுறையாகச் சேர்க்க வேண்டாம்: அவை வேறு secret-ஆல் கையொப்பமிடப்படுகின்றன, ஒவ்வொரு டெலிவரியும் மறுக்கப்படும்.',
'Shopify_Hook_Verified_Client' => 'டெலிவரிகள் ஆப்பின் client secret மூலம் சரிபார்க்கப்படுகின்றன, அது ஏற்கனவே சேமிக்கப்பட்டுள்ளது.',
'Shopify_Hook_Signature_Required' => 'செல்லுபடியான கையொப்பம் இல்லாத டெலிவரிகள் மறுக்கப்படும், எனவே webhooks எதையும் செய்வதற்கு முன் secret அமைக்கப்பட வேண்டும்.',
'Shopify_Hook_Retries' => '2xx பெறும் வரை Shopify மீண்டும் முயற்சிக்கிறது, ஒவ்வொரு டெலிவரியும் ஒருமுறை பதிவுசெய்யப்படும் — மீண்டும் வரும் நிகழ்வு எதையும் செய்யாது, நகல் ஆர்டரை உருவாக்காது.',
'Shopify_No_Signing_Secret' => 'கையொப்ப secret சேமிக்கப்படவில்லை',
'Shopify_No_Signing_Secret_Desc' => 'அது இல்லாமலும் சந்தாக்களை உருவாக்கலாம், ஆனால் ஆப்பின் API secret key இந்த ஸ்டோரில் சேமிக்கப்படும் வரை ஒவ்வொரு டெலிவரியும் மறுக்கப்படும் (Dev Dashboard ஆப்பின் client secret ஏற்கனவே இதை உள்ளடக்குகிறது).',
