'Shopify_Could_Not_Load_Store' => 'இந்த ஸ்டோரை ஏற்ற முடியவில்லை',
'Shopify_G_Lead_Store' => 'இந்தக் கடை ஒத்திசைவாக இருக்கத் தேவையானவை. இங்குள்ள அனைத்தும் இந்த ஸ்டோருக்கு மட்டுமே உரியவை — பாதைகளும் id-களும் உண்மையானவை, எனவே கட்டளைகளை நேரடியாகச் சர்வரில் நகலெடுக்கலாம்.',
'Shopify_G_Lead_Generic' => 'ஒரு Shopify கடை ERP உடன் எவ்வாறு ஒத்திசைவாக இருக்கிறது. அதன் சொந்த நிலையைக் காண மேலே ஒரு ஸ்டோரைத் தேர்வு செய்யவும், அல்லது இப்படியே படிக்கவும் — நீங்கள் எந்த ஸ்டோரை இணைத்தாலும் cron வரியும் webhook URL-உம் ஒன்றே.',
'Shopify_G_Ways_Note' => 'பெரும்பாலான கடைகள் இரண்டையும் இயக்குகின்றன: முதலாவது கடையை நிமிடத்திற்கு நிமிடம் புதுப்பித்த நிலையில் வைத்திருக்கிறது, இரண்டாவது முதலாவது தவறவிட்டதைப் பிடிக்கிறது — ஒருபோதும் வராத webhook, Shopify admin-இல் நேரடியாகச் செய்யப்பட்ட திருத்தம், தளம் செயலிழந்த ஒரு இரவு.',
'Shopify_G_Both_Need' => 'இரு வழிகளுக்கும் முதலில் இது தேவை',
'Shopify_G_Credentials' => 'Shopify நற்சான்றுகள்',
'Shopify_G_Cred_Intro' => 'ஜனவரி 2026 முதல் Shopify நிர்வாகப் பகுதியில் தனிப்பயன் ஆப்களை உருவாக்குவதில்லை, எனவே இரண்டு வகையான இணைப்புகள் உள்ளன:',
'Shopify_G_Cred_DevDash' => '{app} (இப்போது இணைக்கப்படும் எந்தக் கடையும்) — {path}. இந்த ஸ்டோர் ஒத்திசைப்பவற்றுக்கான Admin API scopes-ஐ வழங்கி, ஆப்பைக் கடையில் நிறுவி, பின்னர் ஆப்பின் Settings பக்கத்திலிருந்து {clientId} மற்றும் {clientSecret} ஐ {where} இல் நகலெடுக்கவும். ERP அவற்றை access token ஆகத் தானே மாற்றிக்கொண்டு, ஒவ்வொரு 24 மணிநேரத்திலும் அது காலாவதியாகும் முன் புதுப்பிக்கிறது. client secret webhooks-க்கும் கையொப்பமிடுகிறது, எனவே வேறு எதுவும் தேவையில்லை. ஆப்பும் கடையும் ஒரே Shopify நிறுவனத்தில் இருக்க வேண்டும்.',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard ஆப்',
'Shopify_G_Cred_Legacy' => '{app} (2026-க்கு முன் நிர்வாகப் பகுதியில் உருவாக்கப்பட்டது) — அதன் {token} ({prefix}) மற்றும் webhook கையொப்ப secret ஆக அதன் {secret} உடன் மாற்றமின்றி தொடர்ந்து வேலை செய்யும். இது டோக்கனின் அதே மதிப்பு அல்ல, இவற்றைத் தலைகீழாகப் பயன்படுத்துவதே webhooks மறுக்கப்படுவதற்கான வழக்கமான காரணம்.',
'Shopify_G_Legacy_App' => 'பழைய தனிப்பயன் ஆப்',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'சேமிக்கப்பட்டது',
'Shopify_G_Missing_Refused' => 'காணவில்லை — டெலிவரிகள் மறுக்கப்படும்',
'Shopify_G_Where_Data_Desc' => '{path} இந்தக் கடை விற்கும் இருப்பைக் கொண்ட ERP கிடங்கு, அந்த இருப்பு எழுதப்படும் Shopify இருப்பிடம். இவை இல்லாமல் சரக்கு ஒத்திசைவும் ஆர்டர் இறக்குமதியும் இயங்க மறுக்கும்.',
'Shopify_G_Currently' => 'தற்போது: கிடங்கு {warehouse}, இருப்பிடம் {location}',
