'Shopify_G_Ready' => 'தயார்',
'Shopify_G_Incomplete' => 'முழுமையற்றது',
'Shopify_G_Manual_Syncs' => 'நீங்கள் கைமுறையாகத் தொடங்கும் ஒத்திசைவுகள்',
'Shopify_G_Manual_Desc' => '{centre} இலிருந்து தொடங்கப்படும் ஒத்திசைவு உடனடியாகப் பதிலளித்து பின்னணியில் இயங்கும், ஒவ்வொன்றும் கடைசியாக நின்ற இடத்திலிருந்து தொடரும் சிறு பகுதிகளாக. நீண்ட வலைக் கோரிக்கைகளை முடிக்கும் ஹோஸ்டிங்கால் (LiteSpeed, nginx, load balancer) பெரிய பட்டியல் ஒருபோதும் பாதியில் துண்டிக்கப்படாது, பக்கத்தை மூடுவதும் அதை நிறுத்தாது. அதற்கான worker இன்னும் ஒரு cron வரி:',
'Shopify_G_Cron_Copied' => 'Cron வரி நகலெடுக்கப்பட்டது',
'Shopify_G_Manual_Note' => 'அது இல்லாமலும் ஒத்திசைவு முடியும், ஆனால் Sync Centre பக்கம் திறந்திருக்கும் வரை மட்டுமே: சில வினாடிகளுக்குள் எந்த worker-உம் ஓட்டத்தை எடுக்காவிட்டால், பக்கமே ஒவ்வொரு சிறு கோரிக்கையாக அதைத் தொடரும். Windows-இல் ஒவ்வொரு நிமிடமும் Task Scheduler-ஐப் பயன்படுத்தவும்: நிரல் {program}, arguments {args}, {dir} இல் தொடங்கப்பட்டது.',
