'Shopify_G_Stock_Live' => 'இருப்பு நேரலையில்',
'Shopify_G_Stock_Not_Live' => 'இருப்பு நேரலையில் இல்லை',
'Shopify_G_Realtime_Lead' => 'ஒவ்வொரு மாற்றமும் நிகழும்போதே, வினாடிகளில் அனுப்பப்படும். இரண்டு பகுதிகள், அவை தனித்தனி மாற்றிகள்: {webhooks} கடையின் சொந்த நிகழ்வுகளை உள்ளே கொண்டுவருகின்றன, {push} இருப்பை வெளியே அனுப்புகிறது.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'உடனடி இருப்பு push',
'Shopify_G_Webhooks_In' => 'Webhooks — கடை → ERP',
'Shopify_G_Webhooks_Desc' => 'Shopify-இல் செய்யப்படும் ஆர்டர்கள், ஆர்டர் நிலை மாற்றங்கள், மற்றும் தயாரிப்பு, வாடிக்கையாளர் மற்றும் இருப்புத் திருத்தங்கள். ஸ்டோரைத் திறந்து அதன் {tab} இல் {button} ஐ அழுத்தவும் — இருமுறை அழுத்துவது பாதுகாப்பானது. Shopify இங்கே அனுப்புகிறது:',
'Shopify_G_Webhooks_Tab' => 'Webhooks தாவல்',
'Shopify_G_Webhooks_Note' => 'முகவரி இணையத்திலிருந்து HTTPS மூலம் அணுகக்கூடியதாக இருக்க வேண்டும் — Shopify {localhost} அல்லது {test} டொமைனுக்கு வழங்காது. ஒவ்வொரு டெலிவரியும் ஒருமுறை பதிவுசெய்யப்படுகிறது, எனவே Shopify-இன் மீண்டும் முயற்சிகள் நகல் ஆர்டரை உருவாக்க முடியாது, தோல்வியடைந்ததை மீண்டும் இயக்கலாம். படி 1 இலிருந்து கையொப்ப secret சேமிக்கப்படும் வரை டெலிவரிகள் மறுக்கப்படும்.',
'Shopify_G_Instant_Out' => 'உடனடி இருப்பு push — ERP → கடை',
'Shopify_G_Setting_Missed' => 'மக்கள் தவறவிடும் அமைப்பு இதுதான்',
'Shopify_G_Pos_Not_Auto' => 'ஒரு POS விற்பனை தானாக Shopify-ஐச் சென்றடைவது {not}. அணைத்து வைத்தால், அடுத்த Inventory push படியில் மட்டுமே கடைக்குத் தெரியவரும் — அந்த இடைவெளியில் நீங்கள் ஏற்கனவே கவுண்டரில் விற்ற ஒரு அலகை அது விற்கக்கூடும்.',
'Shopify_G_Not' => 'இல்லை',
'Shopify_G_Tick_Push' => '{where} இல் {setting} ஐத் தேர்வு செய்யவும். அமைப்பு அவ்வளவுதான் — worker இல்லை, cron இல்லை. ஒவ்வொரு விற்பனை, திருப்பல் மற்றும் சரிசெய்தலும் விற்பனை சேமிக்கப்பட்ட உடனே அந்தத் தயாரிப்புகளை மட்டும் அனுப்பும், இருபது வரி விற்பனைக்கு ஒரே ஒரு push, இருபது அல்ல. கவுண்டர் ஒருபோதும் அதற்காகக் காத்திருக்காது.',
'Shopify_G_This_Store' => 'இந்த ஸ்டோர்:',
'Shopify_G_Push_On' => 'இயக்கத்தில் — மாற்றத்தின்போது இருப்பு அனுப்பப்படும்',
'Shopify_G_Push_Off' => 'அணைப்பில் — அட்டவணைப்படி மட்டுமே இருப்பு',
'Shopify_G_Push_Note' => 'ஏற்கனவே Shopify பொருத்தம் உள்ள தயாரிப்புகளும், இந்த ஸ்டோரின் கிடங்கில் உள்ள நகர்வுகளும் மட்டுமே அனுப்பப்படும். மொத்தச் செயல்பாடுகள் — ஒரு தயாரிப்பை நீக்குதல், ஒரு கிடங்கை மீட்டமைத்தல் — நிகழ்வைத் தூண்டாமல் இருப்பை எழுதுகின்றன, திட்டமிட்ட சரக்குப் படியையும் வைத்திருக்க இது ஒரு காரணம்.',
'Shopify_G_Nothing_Install' => 'வேறு எதையும் நிறுவ வேண்டியதில்லை',
'Shopify_G_No_Worker_Note' => 'எந்தப் பகுதிக்கும் queue worker அல்லது cron பதிவு தேவையில்லை. உள்வரும் webhook Shopify செய்யும் கோரிக்கையிலேயே கையாளப்படுகிறது; வெளிச்செல்லும் இருப்பு push விற்பனைக்குச் சேவை செய்த அதே செயல்முறையில், பதில் திரும்பிச் சென்ற {after} இயங்குகிறது — எனவே கவுண்டர் ஒருபோதும் Shopify-க்காகக் காத்திருக்காது, பதிலளிப்பதை நிறுத்தும் கடை பத்து வினாடிகளுக்குப் பிறகு கைவிடப்பட்டு அடுத்த திட்டமிட்ட சரக்கு push-க்கு விடப்படும்.',
'Shopify_G_After' => 'பிறகு',
'Shopify_G_Artisan_Note' => 'ஒரு விதிவிலக்கு: artisan கட்டளையால் செய்யப்படும் இருப்பு மாற்றத்திற்குப் பின்தொடர பதில் இல்லை, எனவே அது {queue} இல் வரிசைப்படுத்தப்படுகிறது. அவையும் உடனடியாக அனுப்பப்பட வேண்டுமெனில், அந்த queue-ஐ இயக்கவும்:',
'Shopify_G_On_Schedule' => 'அட்டவணைப்படி',
'Shopify_G_On_Lower' => 'இயக்கம்',
'Shopify_G_Off_Lower' => 'அணைப்பு',
'Shopify_G_Scheduled_Lead' => 'அனைத்தும் அவ்வப்போது இரு திசைகளிலும் மீண்டும் சரிபார்க்கப்படுகின்றன. நிகழ்நேரத்தைவிட மெதுவானது, ஆனால் உடனடி push பயன்படுத்தாத கடைகளில் இருப்பை அனுப்புவதும், தவறிய webhook-ஐப் பிடிப்பதும், முழுப் பட்டியலையும் நகர்த்தும் ஒரே வழியும் இதுவே.',
'Shopify_G_Cron_Entry' => 'cron பதிவு',
'Shopify_G_Cron_Entry_Desc' => 'அது இல்லாமல் திட்டமிடப்பட்ட எதுவும் இயங்காது. ஒரே வரி, இந்தத் தொகுதிக்கு மட்டும் — நீங்கள் திட்டமிடத் தேர்வு செய்த மற்றவற்றுக்கு அருகில் இதைச் சேர்க்கவும்:',
'Shopify_G_Cron_Note' => 'ஒவ்வொரு ஐந்து நிமிடங்களே ஒரு திட்டம் பயன்படுத்தக்கூடிய மிகச் சிறந்த நுணுக்கம், ஏனெனில் ஐந்து நிமிடங்களே மிகக் குறைந்த படி இடைவெளி. பெரிய இடைவெளியுள்ள பதிவு அடிமட்டமாகிவிடும் — {example} உடன், 5 நிமிடங்களுக்கு அமைக்கப்பட்ட படி ஒவ்வொரு 15 நிமிடங்களுக்கும் இயங்கும். Windows-இல் Task Scheduler-ஐப் பயன்படுத்தவும்: நிரல் {program}, arguments {args}, {dir} இல் தொடங்கப்பட்டது.',
'Shopify_G_Switch_On_Plan' => 'அதை இயக்கி, திட்டத்தைத் தேர்வு செய்யவும்',
'Shopify_G_Plan_Desc' => '{where} மாற்றி cron செயல்பட முடியுமா என்பதைத் தீர்மானிக்கிறது; திட்டம் அது என்ன செய்யும் என்பதைத் தீர்மானிக்கிறது. ஒரு {step} என்பது ஒரு திசையில் ஒரு உருப்படி, தன் சொந்த இடைவெளியுடன் — {first}, {second}. தன் சொந்தப் பெட்டியைக் காலியாக விடும் எந்தப் படியும் இயல்புநிலை இடைவெளியைப் பயன்படுத்தும்.',
'Shopify_G_Step_Lower' => 'படி',
'Shopify_G_Plan_Note' => 'திட்டத்தைக் காலியாக விட்டால், ஸ்டோர் இயல்புநிலை இடைவெளியில் ஆர்டர்களைப் பெற்று இருப்பை அனுப்பும், பெரும்பாலான கடைகள் விரும்புவது அதுவே. ஆர்டர்கள் பெறுதல்-மட்டும்: வாடிக்கையாளர் ஆர்டர் செய்வது Shopify-இல்தான்.',
'Shopify_G_Schedule_On' => 'அட்டவணை இயக்கத்தில்',
'Shopify_G_Schedule_Off' => 'அட்டவணை அணைப்பில் — கைமுறை மட்டும்',
'Shopify_G_When_Step_Runs' => 'ஒரு படி உண்மையில் எப்போது இயங்குகிறது',
'Shopify_G_When_Note' => 'அதே படி கடைசியாகத் {started} அதன் இடைவெளியைவிட அதிக நேரம் கடந்திருந்தால் அந்தப் படி நிலுவையாகும், இது ஓட்ட வரலாற்றிலிருந்து படிக்கப்படுகிறது. எனவே நீங்கள் கைமுறையாகத் தொடங்கும் ஒத்திசைவு அடுத்த தானியங்கி ஒத்திசைவைத் தள்ளிவைக்கும், தொடர்ந்து தோல்வியடையும் படி ஒவ்வொரு tick-இலும் அல்லாமல் அதன் இடைவெளியில் மீண்டும் முயற்சிக்கப்படும். ஸ்டோரின் மேலோட்டம் ஒவ்வொரு படியின் கடைசி ஓட்டம், அடுத்த நிலுவை நேரம், தடுக்கப்பட்டிருந்தால் அதற்கான காரணம் ஆகியவற்றைக் காட்டும். முதல் பட்டியல் push-ஐ அட்டவணையில் வைப்பதற்கு முன் கைமுறையாக இயக்கவும் — முதலில் {dryRun} உடன்.',
'Shopify_G_Started_Lower' => 'தொடங்கியதிலிருந்து',
'Shopify_G_Where_Setting' => 'ஒவ்வொரு அமைப்பும் எங்கே உள்ளது',
'Shopify_G_Where_Setting_Note' => 'இவை அனைத்தும் ஏற்கனவே உள்ள ஸ்டோரில் உள்ளன: {path}, பின்னர் பென்சில் (அல்லது ஸ்டோரின் சொந்தப் பக்கத்தில் {edit}).',
'Shopify_G_Product_Images' => 'தயாரிப்புப் படங்கள்',
'Shopify_G_Img_1' => '{push} இல் படங்கள் தயாரிப்புடன் செல்கின்றன — முதலில் முதன்மைப் படம், பின்னர் கேலரி, பின்னர் சொந்தப் படம் உள்ள ஒவ்வொரு மாறுபாட்டுக்கும் ஒன்று, ஐம்பது வரை.',
'Shopify_G_Products_Push' => 'தயாரிப்பு push',
'Shopify_G_Img_2' => 'ஒரு மாறுபாட்டின் படம் தயாரிப்புடன் பதிவேற்றப்பட்டு பின்னர் {assigned}, Shopify அதை இப்படித்தான் மாதிரியாக்குகிறது: ஒரு மாறுபாடு தயாரிப்பின் படங்களில் ஒன்றைச் சுட்டுகிறது. முதன்மைப் படத்தை மீண்டும் பயன்படுத்தும் மாறுபாடு அதை இருமுறை பதிவேற்றாது.',
'Shopify_G_Assigned' => 'அந்த மாறுபாட்டுக்கு ஒதுக்கப்படுகிறது',
'Shopify_G_Img_3' => 'கோப்பாகச் சேமிக்கப்பட்ட படம் Shopify-க்கு {uploaded}, இணைக்கப்படுவதில்லை, எனவே இந்த நிறுவல் இணையத்திலிருந்து அணுக முடியாதபோதும் அது வேலை செய்யும். ஒட்டப்பட்ட இணைப்பாகச் சேர்க்கப்பட்ட படம் அந்த URL ஆகவே Shopify-க்கு வழங்கப்படும், அது பொதுவில் அணுகக்கூடியதாக இருக்க வேண்டும்.',
'Shopify_G_Uploaded' => 'பதிவேற்றப்படுகிறது',
'Shopify_G_Img_4' => 'அவை உண்மையில் மாறும்போது மட்டுமே மீண்டும் அனுப்பப்படும் — விலையை மட்டும் மாற்றும் push கடையின் படங்களைத் தொடாது, ஏனெனில் அவற்றை அனுப்புவது முழுத் தொகுப்பையும் மாற்றிவிடும்.',
'Shopify_G_Img_5' => 'ERP-இல் ஒரு படத்தை அகற்றுவது அதை Shopify-இல் நீக்குவது {not}. அங்கும் அதை நீக்கவும், இல்லையெனில் கடை அதைத் தொடர்ந்து காட்டும்.',
'Shopify_G_Commands' => 'அறிய வேண்டிய கட்டளைகள்',
'Shopify_G_Command_Copied' => 'கட்டளை நகலெடுக்கப்பட்டது',
