'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash மற்றும் SSLCommerz ஆகியவை ONLINE STORE checkout-இல் மட்டுமே பயன்படுத்தப்படுகின்றன.',
'StoreAdm_PG_Intro_Desc' => 'Stripe விசைகள் உலகளவில் பகிரப்படுகின்றன (நிர்வாகமும் ஆன்லைன் கடையும் ஒரே Stripe ஒருங்கிணைப்பைப் பயன்படுத்துகின்றன). ஒவ்வொரு தாவலும் அதன் முறையை ஆன்லைன் கடை checkout-க்கு இயக்குகிறது அல்லது அணைக்கிறது; Offline Payments அமைப்புக்கு வெளியே செலுத்தப்படும் முறைகளைக் கொண்டுள்ளது.',
'StoreAdm_PG_Used_By_Store_Only' => 'ஆன்லைன் கடை checkout-இல் மட்டுமே பயன்படுத்தப்படுகிறது',
