'StoreAdm_PG_Gw_Secret' => '{gw} Secret',
'StoreAdm_PG_Cards_Off' => 'அட்டைக் கட்டணங்கள் அணைக்கப்பட்டுள்ளன',
'StoreAdm_PG_Cards_Off_Desc' => 'உங்கள் விசைகள் வைத்திருக்கப்படும் — நீங்கள் மீண்டும் இயக்கும் வரை ஆன்லைன் கடை checkout அட்டை விருப்பத்தை வழங்குவதை நிறுத்திவிடும்.',
'StoreAdm_PG_No_Stripe_Key' => 'Stripe விசை எதுவும் சேமிக்கப்படவில்லை',
