'StoreAdm_PG_Paypal_Webhook_Hint' => 'உலாவி redirect ஒருபோதும் வந்து சேராத கட்டணங்களுக்கும், பணத்திருப்பங்கள்/chargeback-களுக்கும் காப்பு. {site}-இல் கீழே உள்ள URL-ஐச் சுட்டும் ஒரு webhook-ஐப் பதிவுசெய்து (நிகழ்வுகள்: {events}) அதன் Webhook ID-ஐ இங்கே ஒட்டவும்.',
'StoreAdm_PG_Webhook_Url' => 'Webhook URL:',
