'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook URL (விருப்பக் காப்பு — Paystack dashboard-இல் Settings → API Keys & Webhooks இன் கீழ் அமைக்கவும்; கோரிக்கைகள் உங்கள் secret key மூலம் HMAC-சரிபார்க்கப்படும்):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'ஆன்லைன் கடை checkout-இல் அட்டைகள், வங்கிப் பரிமாற்றங்கள் மற்றும் mobile money-ஐ ஏற்க, Paystack-ஐ இயக்கி உங்கள் Public மற்றும் Secret விசைகளை ({site} → Settings → API Keys இலிருந்து) உள்ளிடவும்.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhooks, விருப்பத்தேர்வு)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Flutterwave dashboard-இல் Settings → Webhooks இன் கீழ் நீங்கள் அமைத்த Secret Hash; உள்வரும் webhook-களின் {header} header பொருந்தாவிட்டால் அவை நிராகரிக்கப்படும்.',
'StoreAdm_PG_Flutterwave_Info' => 'classic விசைகளுடன் Flutterwave v3 API-ஐப் பயன்படுத்துகிறது. சோதனையா நேரலையா என்பது விசை ஜோடியால் தீர்மானிக்கப்படுகிறது ({keys} எதிர் live விசைகள்) — தனி sandbox சுவிட்ச் இல்லை. கடையின் நாணயம் உங்கள் Flutterwave கணக்கில் இயக்கப்பட்டிருக்க வேண்டும்.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'Webhook URL (விருப்பக் காப்பு — Flutterwave dashboard-இல் மேலே உள்ள Secret Hash உடன் அமைக்கவும்):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'ஆன்லைன் கடை checkout-இல் அட்டைகள், mobile money மற்றும் வங்கிப் பரிமாற்றங்களை ஏற்க, Flutterwave-ஐ இயக்கி உங்கள் v3 Public மற்றும் Secret விசைகளை ({site} → Settings → API இலிருந்து) உள்ளிடவும்.',
