'StoreAdm_PG_Webhook_Secret_Opt' => 'Webhook Secret (விருப்பத்தேர்வு)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'Razorpay dashboard-இல் webhook-ஐ உருவாக்கும்போது நீங்கள் வரையறுக்கும் ரகசியம்; உள்வரும் நிகழ்வுகள் அதற்கு எதிராக HMAC-சரிபார்க்கப்படும், இல்லையெனில் நிராகரிக்கப்படும்.',
