'StoreAdm_PG_Gw_Password' => '{gw} Password',
'StoreAdm_PG_Sandbox_Bkash_Hint' => 'இயக்கத்தில் இருந்தால் உங்கள் sandbox சான்றுகளுடன் {sandbox} பயன்படுத்தப்படும்; {live}-இல் உண்மையான bKash கணக்குகளில் வசூலிக்க அணைக்கவும்.',
'StoreAdm_PG_Bkash_Info' => 'bKash Tokenized Checkout-ஐப் பயன்படுத்துகிறது (bKash merchant portal-இலிருந்து வணிகர் சான்றுகள்). bKash BDT-இல் மட்டுமே வசூலிக்கிறது — கடையின் செயலில் உள்ள நாணயம் BDT ஆக இருக்கும்போது மட்டுமே checkout-இல் இந்த விருப்பம் வழங்கப்படும்.',
'StoreAdm_PG_Bkash_Disabled_Desc' => 'ஆன்லைன் கடை checkout-இல் வாடிக்கையாளர்கள் bKash மூலம் செலுத்த, bKash-ஐ இயக்கி உங்கள் Tokenized Checkout App Key, App Secret, Username மற்றும் Password-ஐ (bKash merchant portal-இலிருந்து) உள்ளிடவும்.',
