'StoreAdm_PG_Sandbox_Sslcommerz_Hint' => 'இயக்கத்தில் இருந்தால் sandbox சான்றுகளுடன் {sandbox} பயன்படுத்தப்படும்; {live}-இல் உண்மையான வாடிக்கையாளர்களிடம் வசூலிக்க அணைக்கவும்.',
'StoreAdm_PG_Sslcommerz_Info' => 'பங்களாதேஷில் அட்டைகள், bKash/Nagad/Rocket mobile banking மற்றும் இணைய வங்கியை உள்ளடக்கிய hosted checkout. சான்றுகள் உங்கள் SSLCommerz merchant panel-இலிருந்து வருகின்றன (Store ID + Store Password / API சான்றுகள்).',
